COLLDATA("jamulfawaid","ur",[[3809,"سیدہ عائشہ رضی اللہ عنہا کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: وادی بطحان جنت کی برکات میں سے ایک برکت کا مقام ہے۔‘‘ (البزار)","",{"k":"بزار: 1200، فيه راوٍ لم يسم، هيثمي: 5918۔"}],[3810,"سیدنا عبداللہ ابن عباس رضی اللہ عنہما سے روایت ہے کہ سیدنا عمر فاروق رضی اللہ عنہ نے فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، جبکہ آپ صلی اللہ علیہ وسلم وادی عقیق میں تھے، فرمایا: آج رات میرے رب کی طرف سے ایک فرشتہ آیا اور اس نے کہا: اس مبارک وادی میں نماز پڑھو اور کہو: عمرہ حج میں داخل ہے۔‘‘ (البخاری)","",{"k":"بخاری (1534)، ابوداؤد (1800)، ابن ماجہ (2976)، احمد (162)۔","e":"ایک وادی عقیق مدینہ کے اندر تھی یہ وہ نہیں یہ وہ وادی ہے جو ذوالحلیفہ کے قریب ہے، یہ مدینہ منورہ سے چار میل کے فاصلہ پر ہے، آنے والے حضرت جبریل علیہ السلام تھے۔\n۲۔ ثابت ہوا یہ وادی بھی فضیلت والی ہے اور اس میں نماز پڑھنا بھی بہتر کام ہے، اگرچہ نماز یہاں فرض نہیں تاہم تاکید ہے کہ کوشش کی جائے۔ ۳۔ اس میں حج قران کے افضل ہونے پر بھی دلیل دی گئی ہے کیونکہ آپ نے فرمایا: کہہ دو عمرہ حج میں داخل ہے۔ مگر یہ استدلال درست نہیں، حج تمتع ہی افضل ہے۔ نبی صلی اللہ علیہ وسلم نے حج قران اس لیے کیا تھا کہ آپ نے قربانی کے جانور ساتھ لے لیے تھے، وگرنہ پسند آپ نے حج تمتع ہی کیا تھا۔ (مرعاۃ: ۷/۳۸۴)"}],[3811,"امام مالک رحمہ اللہ فرماتے ہیں: کسی کے لیے مناسب نہیں ہے کہ وہ مقام معرس سے تجاوز کرے، جبکہ وہ مدینہ منورہ کی طرف لوٹ رہا ہو، یہاں تک اس جگہ میں نماز پڑھے اور جتنی چاہے پڑھ لے۔ اس لیے کہ مجھے یہ خبر پہنچی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے یہاں پڑاؤ ڈالا تھا۔ (ابوداؤد)","",{"k":"ابوداؤد (2045)، صحیح، مقطوع، البانی: 1799۔","e":"معرس رات کو آرام کرنے کی جگہ کو کہتے ہیں، یہ ذوالحلیفہ سے چھ میل کے فاصلہ پر ہے، یہاں اترنا حج کا طریقہ نہیں، یہاں صرف نبی اکرم صلی اللہ علیہ وسلم اترے تھے، لوگ آپ کے اس طریقہ پر حج کا طریقہ سمجھ کر نہیں، صرف آپ کی اقتداء میں اترتے ہیں۔ پھر صبح یہاں سے مدینہ کی طرف کوچ کرتے، یہ حج سے یا سفر سے واپسی اترتے تھے۔ تاکہ گھر والوں کو اطلاع ہو جائے کیونکہ اچانک سفر سے گھر آنے کی ممانعت ہے۔ (عون المعبود: ۲/۱۷۳)"}],[3812,"سیدنا سعد بن خثیمہ رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: میں نے دیکھا گویا بنو سالم اور بنو بیاضہ کے درمیان رحمت برس رہی ہے لوگوں نے عرض کیا: یا رسول اللہ صلی اللہ علیہ وسلم! کیا ہم اس جگہ منتقل ہو جائیں؟ فرمایا: نہیں، لیکن اس جگہ کو قبرستان بنالو۔ پس انھوں نے اپنے مردے وہاں دفنانے شروع کر دیے۔‘‘ (الکبیر، سند کمزور)","",{"k":"طبرانی کبیر: 5416، فيه، يعقوب بن محمد الزهري وفيه كلام كثير، وقد وثق، هيثمي: 5907۔"}],[3813,"سیدہ ام قیس رضی اللہ عنہا فرماتی ہیں کہ کاش تو مجھے دیکھتا کہ جب رسول اللہ صلی اللہ علیہ وسلم نے میرا ہاتھ مدینہ کی گلی میں پکڑا اور اس گلی میں اس وقت کوئی گھر نہ تھا یہاں تک کہ آپ صلی اللہ علیہ وسلم بقیع الغرقد تک آئے اور فرمایا: اے ام قیس! میں نے کہا: اے اللہ کے رسول صلی اللہ علیہ وسلم! میں حاضر ہوں، فرمایا: کیا تو قبرستان دیکھتی ہے؟ اللہ تعالیٰ اس قبرستان سے قیامت کے دن ستر ہزار انسان اٹھائے گا جن کی صورت چودھویں کے چاند کی طرح روشن ہوں گی۔ وہ جنت میں بغیر حساب کے جائیں گے۔ پس سیدنا عکاشہ رضی اللہ عنہ نے کہا: میں بھی اے اللہ کے رسول صلی اللہ علیہ وسلم! آپ نے فرمایا: اور تو بھی، پھر دوسرے آدمی نے کہا: اور میں بھی اے اللہ کے رسول! فرمایا: عکاشہ تجھ پر سبقت لے گیا ہے۔ (الکبیر سند مخفی ہے)","",{"k":"طبرانی کبیر: 25 / 181، فيه من لم اعرفه، هيثمي: 5908۔","e":"انتباہ: ...... حضرت عکاشہ اور ستر ہزار افراد بغیر حساب میں جنت میں جائیں گے یہ تو ثابت ہے۔ (بخاری) مگر مدینہ کے ساتھ خاص کرنا ثابت نہیں۔ اور نہ ہی کسی صحیح حدیث سے ثابت ہے کہ آپ نے کبھی کسی غیر محرم عورت کا ہاتھ پکڑا ہوا۔"}],[3814,"سیدنا ابوسعید رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اے فاطمہ! اپنی قربانی کی طرف اٹھ کر جاؤ اور اس پر حاضر رہو۔ اس کے خون کے ہر قطرے کے بدلے تیرے سابقہ گناہ معاف ہوں گے۔ عرض کیا: یا رسول اللہ! یہ بشارت ہم اہل بیت کے لیے مخصوص ہے یا سب مسلمانوں کے لیے ہے؟ فرمایا: بلکہ یہ ہمارے لیے بھی ہے اور سب مسلمانوں کے لیے بھی ہے۔‘‘ (البزار، سند کمزور)","",{"k":"بزار: 1202، فيه عطية بن قيس وفيه كلام كثير، وقد وثق، هيثمي: 5934۔"}],[3815,"الکبیر اور الاوسط کی ضعیف سند کے ساتھ ایک روایت عمران بن حصین رضی اللہ عنہ سے بھی اسی طرح کی ہے۔ لیکن اس روایت میں یہ بیان زائد ہے کہ فرمایا: اے فاطمہ رضی اللہ عنہا! یہ کہو: میری نماز، میری قربانی، میری زندگی ............ تا آخر آیت۔","",{"k":"طبرانی کبیر: 18 / 239۔","e":"یہ دعائیں سند کے لحاظ سے تو صحیح ثابت نہیں، اگر کوئی گنجائش نکلتی بھی ہے تو یہ قربانی کو زمین پر لٹانے سے پہلے پڑھی جائیں، زمین پر قربانی لٹانے کے بعد بسم اللہ اکبر کہیں اور ذبح کر دیں۔ (مرعاۃ: ۲/۳۵۸)"}],[3816,"سیدنا ابن عباس رضی اللہ عنہما کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے قربانی کے دن کے متعلق فرمایا: آج کے دن کسی انسان نے ایسا کوئی عمل نہیں کیا جو خون بہانے سے زیادہ افضل ہو البتہ اگر کسی نے صلہ رحمی کی ہے تو وہ افضل ہے۔‘‘ (الکبیر، سند کمزور ہے)","",{"k":"طبرانی کبیر: 10948، فيه الحسن، بن يحيى الخشني وهو ضعيف، وقد وثقه جماعة، هيثمي: 5939۔","e":"منکرین قربانی بہت کوشش کرتے ہیں کہ اس کی حیثیت ختم کی جائے، کبھی کہتے ہیں جانوروں پر ظلم ہے، کبھی کہتے ہیں گوشت ضائع ہوتا ہے، کبھی کہتے ہیں، کسی غریب کی بیٹی کے نکاح پر اتنے پیسے خرچ کریں تو فائدہ ہو۔ بہر حال یہ ان کی موشگافیاں ہیں، اللہ تعالیٰ اور اس کے رسول کی بات نہیں ہے۔ یہ حدیث اور اس جیسی دیگر احادیث دلالت کرتی ہیں کہ قربانی کے دن کے تمام اعمال میں سے اللہ تعالیٰ کے ہاں پسندیدہ عمل جانور قربانی کرنا ہے، اس دن کروڑوں روپے کا خرچ اس محبوب عمل کے برابر نہیں ہوسکتا۔ (مرعاۃ: ۲/۳۶۲)"}],[3817,"سیدنا مخنف بن سلیم رضی اللہ عنہ کا بیان ہے کہ ہم میدان عرفات میں رسول اللہ صلی اللہ علیہ وسلم کے پاس کھڑے تھے کہ آپ صلی اللہ علیہ وسلم نے فرمایا: لوگو! ہر گھرانے پر ہر سال قربانی لازم ہے اور عتیرہ بھی لازم ہے۔ اور کیا تمہیں معلوم ہے کہ عتیرہ کیا ہے؟ یہ وہی ہے جس کو تم رجبیہ کہتے ہو۔ (ترمذی)","",{"k":"ترمذی (1518)، صحیح، البانی: 1225، نسائی (4224)، ابوداؤد (2788)، ابن ماجہ (3125)، احمد (17432)۔"}],[3818,"جبلہ بن سحیم سے روایت ہے کہ سیدنا عبداللہ ابن عمر رضی اللہ عنہما سے ایک آدمی نے سوال کیا: کیا قربانی واجب ہے؟ تو سیدنا عبداللہ ابن عمر رضی اللہ عنہما نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم اور مسلمانوں نے قربانی کی ہے۔ آدمی نے دوبارہ پھر یہی بات کہی۔ (ترمذی)","",{"k":"ترمذی (1506)، ضعیف، البانی: 260، ابن ماجہ (3124)۔"}],[3819,"سیدنا عبداللہ ابن عمر رضی اللہ عنہما سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم دس سال مدینہ میں ٹھہرے اور قربانی دیتے رہے۔‘‘ (الترمذی)","",{"k":"ترمذی (1507)، ضعیف، البانی: 261، احمد (4935)۔"}],[3820,"سیدنا ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جس کو قربانی دینے کی وسعت ہو اور وہ نہ دے تو وہ ہماری عیدگاہ کے قریب نہ آئے۔‘‘ (ابن ماجہ)","",{"k":"ابن ماجہ (3123)، حسن، البانی: 2532، احمد (8074)۔"}],[3821,"سیدنا عبداللہ ابن عمرو بن العاص رضی اللہ عنہما کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: مجھے قربانی کے دن کو عید بنانے کا حکم دیا گیا ہے، اللہ تعالیٰ نے اس امت کے لیے اس دن کو عید قرار دیا ہے۔ ایک آدمی نے سوال کیا، یا رسول اللہ صلی اللہ علیہ وسلم! آپ یہ بتائیں کہ اگر میرے پاس صرف دودھ دینے والی قربانی ہو تو کیا میں وہ ذبح کر دوں؟ فرمایا: نہیں۔ لیکن تو اپنے بال اپنے ناخن اور موچھیں کترا دے اور اپنے زیر ناف بال صاف کر دے تو یہ اللہ تعالیٰ کے نزدیک تمہاری پوری قربانی شمار ہو گی۔‘‘ (ابو داؤد)","",{"k":"ابوداؤد (2789)، ضعیف، البانی: 595، نسائی (4365)۔","e":"قربانی کی مشروعیت پر قرآن پاک کی یہ آیت دلالت کرتی ہے۔ ﴿فَصَلِّ لِرَبِّكَ وَانْحَرْ﴾ (الکوثر: ۲) ’’اپنے رب کے لیے نماز پڑھ اور قربانی کر۔‘‘ اور قربانی سنت ابراہیمی ہے۔ ارشاد باری تعالیٰ ہے: ﴿وَفَدَيْنَاهُ بِذِبْحٍ عَظِيمٍ﴾ (الصافات: ۱۰۷) ’’اور ہم نے اس کے فدیہ میں عظیم قربانی دی۔‘‘ یعنی حضرت ابراہیم علیہ السلام جو بیٹے اسماعیل علیہ السلام کو ذبح کرنے پر عمل پیرا ہوئے تو ہم نے انہیں بچا کر ایک بکرا قربان کر دیا، اور اس دن سے یہ سنت ابراہیمی قرار پائی۔ ۲۔ قربانی واجب، سنت موکدہ، یا مستحب ہے، اس بارے میں ائمہ کا اختلاف ہے۔ علامہ عبید اللہ رحمانی رحمہ اللہ، شوکانی رحمہ اللہ کے حوالے سے لکھتے ہیں: أَنَّ الْحَقَّ مَا قَالَهُ الْأَقَلُّوْنَ مِنْ كَوْنِهَا وَاجِبَةً وَلَكِنْ هَذَا الْوُجُوْبَ مُقَيَّدٌ بِالسَّعَةِ فَمَنْ لَا سَعَةَ لَهُ لَا أُضْحِيَّةَ عَلَيْهِ. (مرعاۃ: ۲/۳۵۰) ’’حق بات یہی ہے جو کم ائمہ کرام نے کہی ہے کہ قربانی واجب ہے لیکن اس کا واجب ہونا گنجائش کے ساتھ مقید ہے یعنی جس کے پاس گنجائش نہیں اس پر قربانی واجب نہیں ہے۔ ۳۔ نبی اکرم صلی اللہ علیہ وسلم نے وہ بکری ذبح کرنے سے اس لیے منع کیا تھا کہ اس کے پاس اس کے سوا اور کوئی بھیڑ، بکری نہیں تھی جس سے فائدہ اٹھائے، یا پھر وہ اسے کسی نے دودھ تک کے لیے تحفہ دی تھی اس کے ذہن میں نہیں تھا کہ وہ تو اصل مالک کو واپس کرنی ہے اس لیے آپ صلی اللہ علیہ وسلم نے اسے ذبح کرنے سے منع کر دیا۔ اور عید کے دن ناخن اور بال ترشوانا وغیرہ اعمال کو قربانی کے ثواب کے برابر قرار دیا گیا ہے گویا کہ اس طرح دوسرے لوگوں کے ساتھ ثواب و مسرت میں شرکت ہو جاتی ہے۔\n۴۔ رجب میں ذبح ہونے والی بکری کو عتیرہ کہتے تھے، اس بارے میں وارد احادیث سے ایک قول یہ ہے کہ یہ منسوخ ہو چکا ہے، اب اسے ذبح کرنا منع ہے۔ بعض احادیث سے اس کا ثبوت ملتا ہے۔ معتدل قول یہی ہے کہ اگر جاہلیت کی طرح دن مقرر نہ ہو تو رجب میں جانور ذبح کرنے کی ممانعت نہیں ہے۔ غیر اللہ کی بجائے خالص اللہ کے لیے جانور ذبح کیا جائے۔ منسوخ صرف جاہلی طریقہ ہے، رجب میں بکری ذبح کرنا منسوخ نہیں ہے۔ (مرعاۃ: ۲/۳۶۶)"}],[3822,"نافع بیان کرتے ہیں کہ سیدنا عبداللہ ابن عمر رضی اللہ عنہ ماں کے پیٹ کے بچے کی طرف سے قربانی نہیں ادا کرتے تھے۔‘‘ (مالک)","",{"k":"مؤطا (1053)۔","e":"کیونکہ پیٹ میں بچے کی طرف سے قربانی درست نہیں، نہ اس کی پابندی ہے۔ (شرح زرقانی: ۳/۷۹)"}],[3823,"سیدنا عبداللہ ابن عباس رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ہم ایک سفر میں تھے کہ عید الاضحیٰ آ گئی، پس ہم سات افراد گائے کی قربانی دینے میں شریک ہوئے اور دس آدمی اونٹ میں شریک ہوئے۔‘‘ (الترمذی)","",{"k":"ترمذی (1501)، صحیح، البانی: 1214، نسائی (4392)، ابن ماجہ (3131)۔","e":"یہ حدیث دلالت کرتی ہے کہ گائے میں سات آدمی قربانی کے حصہ دار بن سکتے ہیں، یعنی سات آدمی مل کر ایک گائے قربانی کریں اور جو قیمت حصہ میں آتی ہے وہ اکٹھی ادا کر دیں تو ساتوں کی قربانی ہو جاتی ہے۔ اور اونٹ میں دس آدمی شرکت کر سکتے ہیں۔ بعض لوگ عام قربانی اور حج کی قربانی کی تفریق کرتے ہیں یہ درست نہیں، اکیلا طاقت رکھتا ہے تو اکیلا قربانی کرے اگر شرکت کرنا چاہیں تو عید قربان کے موقع پر اور حج کے موقع پر اونٹ میں دس اور گائے میں سات آدمی شریک ہو سکتے ہیں۔ (مرعاۃ: ۲/۳۵۵)"}],[3824,"عمارہ بن صیاد نے کہا، مجھے عطاء بن یسار نے خبر دی، اس نے کہا، مجھے ابو ایوب انصاری نے بیان کیا کہ مدینہ میں ہم لوگ ایک بکری کی قربانی کرتے تھے۔ ایک آدمی اپنے اہل و عیال کی طرف سے بکری ذبح کرتا تھا۔ پھر بعد میں لوگوں نے اس کو باعث فخر بنایا تو قربانی فخر یہ علامت بن گئی۔‘‘ (مالک)","",{"k":"مؤطا (1050)۔"}],[3825,"سیدنا عبداللہ ابن عمر رضی اللہ عنہ کا قول ہے کہ قربانی میں جماعت شامل نہ ہو گی۔ یہ صرف ایک گھر کے افراد کے لیے ہے۔‘‘ (رزین)","",{"k":"رزین۔","e":"مطلب یہ ہے کہ ہر گھر والا ایک قربانی اور ایک سے زیادہ بھی کر سکتا ہے، بشرطیکہ اللہ تعالیٰ کی قربت کے لیے ہو۔ اگر زیادہ قربانی کرنے سے فخر و مباہات میں مقابلہ مقصد ہو تو پھر سارے اہل خانہ کے لیے ایک ہی بکری کافی ہے۔ زیادہ نہ ہی کی جائیں تو بہتر ہے۔ (شرح زرقانی: ۳/۷۴)"}],[3826,"سیدنا ابو امامہ رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: بہترین قربانی مینڈا ہے اور بہترین کفن دو کپڑے کا ہے۔‘‘ (الترمذی)","",{"k":"ترمذی (1517)، ضعیف، البانی: 263، ابن ماجہ (3130)۔","e":"صحیح حدیث سے یہ ثابت ہوتا ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے سینگوں والا مینڈھا قربانی کیا، جو خصی تھا، سیاہ پاؤں اور سیاہ منہ والا تھا۔ (ترمذی)"}],[3827,"سیدنا جابر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے حج کے دوران اپنی ازواج مطہرات کی طرف سے ایک گائے کی قربانی کی۔‘‘","",{"k":"مسلم (1319)، احمد (14621)۔"}],[3828,"سیدنا جابر رضی اللہ عنہ بیان کرتے ہیں کہ قربانی کے دن عائشہ رضی اللہ عنہا کی طرف سے رسول اللہ صلی اللہ علیہ وسلم نے ایک گائے کی قربانی دی تھی۔ (مسلم)","",{"k":"مسلم (1319)، احمد (14621)۔","e":"دونوں میں مطابقت یوں ہے کہ ساری بیویوں کی طرف سے بھی قربانی کی اور سیدہ عائشہ رضی اللہ عنہا کے لیے ایک گائے خاص قربانی دی۔ (مرعاۃ: ۴/۲)"}],[3829,"حنش رضی اللہ عنہ کا بیان ہے کہ میں نے علی رضی اللہ عنہ کو دو مینڈھے قربانی کرتے دیکھا تو میں نے پوچھا: یہ کیا ہے؟ فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے مجھے وصیت کی تھی کہ میں آپ صلی اللہ علیہ وسلم کی طرف سے قربانی کروں۔ اس لیے آپ صلی اللہ علیہ وسلم کی طرف سے میں قربانی کرتا ہوں۔ (ابو داؤد)","",{"k":"ابوداؤد (2790)، ضعیف، البانی: 596، ترمذی (1495)۔","e":"حنش کی وجہ سے یہ روایت ضعیف ہے اس لیے حجت نہیں۔ اگر بقول بعض اسے حسن درجہ کی تسلیم بھی کر لیا جائے تو اس سے یہ دلیل لینا مناسب نہیں کہ میت کی طرف قربانی جائز ہے۔ کیونکہ اس میں صرف میت کی طرف سے قربانی نہیں سیدنا علی رضی اللہ عنہ تھے جو وصیت پر عمل کرتے تھے، دوسرے لوگ اس میں شامل نہیں۔ دوسری حدیث کے الفاظ یہ ہیں اور ایک میرے اور میرے اہل خانہ کی طرف سے دوسرا مینڈھا اس کے لیے جو میری امت میں سے قربانی نہیں کر سکا۔ اس میں زندہ اور مردہ سب شامل ہیں لہذا ثابت ہوا کہ قربانی کے ثواب میں گھر کے مردہ اور زندہ تمام افراد کو شامل کرنا جائز ہے، صرف میت کی طرف سے قربانی کا ثبوت نہیں۔ (مرعاۃ: ۲/۳۵۸)"}],[3830,"ابو کباش کہتے ہیں: عید قربان کے موقع پر میں مدینہ کی طرف ایک سال کے بھیڑ کے بچے لایا اور ان سے فائدہ نہ ہوا اور وہ فروخت نہ ہوئے تو میں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے ملاقات کی اور ان سے پوچھا: تو اس نے کہا: میں نے نبی کریم صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: بہترین قربانی بھیڑ کا ایک سالہ بچہ ہے۔ پس لوگ ان کو اٹھا کر لے گئے۔‘‘ (ترمذی)","",{"k":"ترمذی (1499)، ضعیف، البانی: 258، احمد (9446)۔"}],[3831,"سیدنا براء بن عازب رضی اللہ عنہ نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنی انگلیوں سے اشارہ کر کے فرمایا: جس جانور کا لنگڑا پن ظاہر ہو اور جو آنکھ سے کانا ہو اور اس کا کانا پن ظاہر ہو۔ اور جس کی ہڈی کا مغز نہ ہو۔ وہ جانور قربانی کے لیے جائز نہیں۔‘‘ (نسائی)","",{"k":"نسائی (4371)، صحیح، البانی: 4075، ترمذی (1497)، ابوداؤد (2803)، ابن ماجہ (3144)، احمد (18200)، مؤطا (1041)، دارمی (1950)۔"}],[3832,"سیدنا علی رضی اللہ عنہ بیان کرتے ہیں کہ ہمیں رسول اللہ صلی اللہ علیہ وسلم نے حکم دیا ہے کہ ہم آنکھ اور کان اچھی طرح دیکھیں۔ اور حکم دیا ہے کہ قربانی نہ کی جائے مقابلہ کی، نہ مدابرہ کی، نہ شرقاء کی، اور نہ خرقاء کی۔ مقابلہ وہ ہے جس کے کان کو ایک طرف سے کاٹا گیا ہو۔ مدابرہ وہ ہے جس کے کان کو ایک پہلو سے کاٹا گیا ہو، شرقاء وہ جس کا کان چیرا گیا ہو، خرقاء وہ ہے جس کے کان میں سوراخ ہو۔‘‘ (ترمذی)","",{"k":"ترمذی (1498)، ضعیف، البانی: 256، نسائی (4376)، ابوداؤد (2804)، ابن ماجہ (3143)، احمد (1311)، دارمی (1951)۔"}],[3833,"یزید ذو مصر نے کہا کہ میں عقبہ بن عبد السلمی کے ہاں گیا اور میں نے کہا: اے ابو ولید! میں قربانی کے لیے حیوان کی تلاش میں نکلا تو مجھے کوئی حیوان پسند نہ آیا، مگر ایک حیوان جس کے دانت ٹوٹے ہوئے ہیں۔ پس میں نے اس کی قربانی بھی مکروہ سمجھی ہے۔ عتبہ نے کہا: وہ حیوان میرے لیے نہیں لائے گا؟ میں نے کہا: سبحان اللہ! تیری طرف سے جائز ہوگا اور میری طرف سے جائز نہ ہوگا؟ اس نے کہا: ہاں، اس لیے کہ تو شک کرتا ہے اور میں شک نہیں کرتا۔ رسول اللہ صلی اللہ علیہ وسلم نے مصفرہ، مستاصلہ، بحقاء، مشیعہ اور الکسیراء کی قربانی کی ممانعت فرمائی ہے۔ (ابو داؤد)","",{"k":"ابوداؤد (2803)، ضعیف، البانی: 599، احمد (17200)۔","m":"المصفرہ وہ جس کا کان جڑ سے کاٹا گیا ہو اور کان کا سوراخ نظر آتا ہو۔ المستاصلہ وہ جس کا سینگ جڑ سے نکلا ہوا ہو۔ البخقاء جس کی بینائی جاتی رہے۔ المشيعہ وہ جو بکریوں کے ریوڑ کے ساتھ نہ چل سکتی ہو لنگڑا ہو یا کمزور ہو۔ الكسراء وہ جس کی ہڈی ٹوٹی ہوئی ہو۔"}],[3834,"سیدنا ابو سعید خدری رضی اللہ عنہ کہتے ہیں: ہم نے مینڈھا خریدا تاکہ ہم قربانی دیں، لیکن بھیڑیا اس کی چکی یا کان کاٹ کر لے گیا۔ پس ہم نے رسول اللہ صلی اللہ علیہ وسلم سے دریافت کیا تو آپ صلی اللہ علیہ وسلم نے ہمیں اس کی قربانی دینے کا حکم دیا۔‘‘ (ابن ماجہ سند ضعیف ہے)","",{"k":"ابن ماجہ (3146)، ضعیف الاسناد جداً: 679، احمد (11411)۔","e":"ان احادیث سے ثابت ہوتا ہے کہ نصف سے زیادہ کان یا سینگ کا کٹا ہو تو قربانی جائز نہیں اس سے کم ہو تو گنجائش ہے۔ ۲۔ اور اگر ایک جانور قربانی کے لیے منتخب کر لیا ہو اس کے بعد عیب ناک ہو جاتا ہے تو بہتر یہ ہے اگر طاقت ہے تو اسے تبدیل کیا جائے بے عیب جانور ذبح کیا جائے اگر طاقت نہیں تو پھر مجبوری ہے۔ ۳۔ ان میں سے صحیح احادیث میں جو عیب بیان ہوئے ہیں، ان سے قربانی پاک ہونی چاہیے، اگر کوئی ان عیب والی قربانی کرتا ہے تو قربانی قبول نہ ہوگی۔ (مرعاۃ: ۲/۳۵۹)"}],[3835,"سیدنا براء بن عازب رضی اللہ عنہما نے کہا: میرے ماموں سیدنا ابو بردہ رضی اللہ عنہ نے نماز عید سے پہلے اپنی قربانی ذبح کر دی، تو آپ صلی اللہ علیہ وسلم نے فرمایا: تیری بکری صرف گوشت کے لیے ہے۔ اس نے کہا: یا رسول اللہ صلی اللہ علیہ وسلم! میرے گھر کی بکری کا جزعہ بچہ ہے (ایک سال کا) فرمایا تو وہی ذبح کر دے اور تیرے علاوہ کسی کے لیے ایسا حیوان جائز نہ ہوگا۔ پھر فرمایا: جس نے نماز سے پہلے ذبح کیا اس نے اپنے کھانے کے لیے ذبح کیا اور جس نے بعد نماز کے ذبح کیا تو اس کی قربانی مکمل ہو جائے گی اور وہ مسلمانوں کے طریقے کو پائے گا۔‘‘ (بخاری)","",{"k":"بخاری (5556)، مسلم (1961)، ترمذی (1508)، نسائی (1563)، ابوداؤد (2801)، احمد (18218)، دارمی (1962)۔"}],[3836,"سیدنا براء بن عازب رضی اللہ عنہ بیان کرتے ہیں: قربانی کے دن رسول اللہ صلی اللہ علیہ وسلم نے ہمیں خطبہ دیا اور فرمایا نماز پڑھنے سے پہلے تم میں سے کوئی شخص قربانی نہ کرے۔ پس میرا ماموں آپ صلی اللہ علیہ وسلم کے سامنے کھڑا ہوا۔ عرض کی: یا رسول اللہ صلی اللہ علیہ وسلم! آج کے دن گوشت عام ہونے کی وجہ سے پسند نہیں کیا جاتا اس لیے میں نے اپنی قربانی جلدی ذبح کر دی تاکہ میں گھر کے افراد اہل محلہ اور ہمسائیوں کو گوشت کھلاؤں فرمایا: اس کے قائم مقام دوسری قربانی ذبح کر دے اس نے عرض کیا: یا رسول اللہ صلی اللہ علیہ وسلم! میرے پاس دودھ پیتا بکری کا بچہ ہے جو دو بکریوں سے گوشت میں بہتر ہے تو کیا میں اس کو ذبح کر دوں؟ فرمایا: ہاں، وہ تیری دونوں قربانیوں سے بہت بہتر ہے اور بکری کا سال کی عمر کا بچہ تیرے سوا کسی کی طرف سے قربانی کے لیے جائز نہ ہوگا۔‘‘","",{"k":"ترمذی (1508)، صحیح، البانی: 1217، بخاری (5556)، مسلم (1961)، نسائی (1563)، ابوداؤد (2801)، احمد (18012)، دارمی (1962)۔"}],[3837,"سیدنا جابر رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے مدینہ میں قربانی کے دن ہمیں نماز پڑھائی، پس چند آدمی اٹھے اور انہوں نے اپنی قربانیاں ذبح کر دیں۔ انہیں گمان تھا کہ نبی کریم صلی اللہ علیہ وسلم نے قربانی ذبح کر دی ہوگی۔ پس آپ صلی اللہ علیہ وسلم نے حکم دیا کہ جس نے آپ صلی اللہ علیہ وسلم کی قربانی ذبح کرنے سے پہلے ذبح کی ہے وہ اس کے بدلے دوسری قربانی ذبح کرے۔ (مسلم)","",{"k":"مسلم (1964)، احمد (14062)۔","e":"نبی صلی اللہ علیہ وسلم سے پہلے جانور قربانی کرنے والوں کو حکم دیا گیا تھا کہ دوبارہ قربانی دہرائیں۔ یہ اللہ کے نبی صلی اللہ علیہ وسلم سے آگے بڑھنے کی صورت تھی جس پر احتیاطاً آپ نے سرزنش فرمائی۔ اب حکم یہی ہے کہ قربانی کا وقت نماز کی ادائیگی جب امام کر لیتا ہے، تو اس سے شروع ہو جاتا ہے، اس میں شہر والے اور دیہات والے سب شامل ہیں، اور نماز سے پہلے قربانی کی ہو تو یہ قربانی نہیں عام گوشت کا جانور ہے۔ اگر طاقت ہو تو اس کے عوض نماز کے بعد اور قربانی کی جائے۔ اگر طاقت نہیں تو یہ قربانی نہ ہوگی۔ (مرعاۃ: ۲/۳۳۶)"}],[3838,"سیدنا ابن عمر رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم اپنی قربانی عید گاہ میں ذبح کرتے تھے اور سیدنا ابن عمر رضی اللہ عنہ بھی ایسا ہی کرتے تھے۔‘‘ (ابوداؤد)","",{"k":"ابوداؤد (2811)، حسن، صحیح، البانی: 2437، نسائی (4366)، ابن ماجہ (3161)، احمد (5842)۔","e":"اس سے بعض ائمہ نے اخذ کیا ہے کہ قربانی کے کل تین ایام ہیں، ایک دن قربانی کا اور دو دن بعد والے۔ لیکن یہ قول کمزور ہے ایک تو خود سیدنا علی رضی اللہ عنہ سے بیان کیا گیا ہے کہ قربانی کے دن پہلے دن کے بعد تین دن اور ہیں۔ (بیہقی: ۹/۲۹۷، محلی ابن حزم: ۷/۳۷۷) دوسری بات یہ ہے کہ سیدنا جبیر بن مطعم رضی اللہ عنہ بیان کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: كُلُّ أَيَّامِ التَّشْرِيقِ ذَبْحٌ (ابن حبان، بیہقی، حوالہ مذکور) تمام ایام تشریق قربانی ذبح کرنے کے دن ہیں اور ایام تشریق پہلے دن کے علاوہ جسے یوم نحر کہتے ہیں، تین دن ہیں، تین دن اور ہیں۔ کل چار دن قربانی کے ہوئے۔ (مرعاۃ: ۲/۳۶۴)"}],[3839,"نافع کا بیان ہے کہ سیدنا عبداللہ ابن عمر رضی اللہ عنہ نے فرمایا: قربانی کے دن کے بعد مزید دو دن قربانی کی جاسکتی ہے۔‘‘ (مالک)"],[3840,"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے سینگوں والے مینڈھے کا حکم دیا جس کے پاؤں سیاہ، سینہ سیاہ اور آنکھیں سیاہ ہوں، پس ایسا مینڈھا لایا گیا تاکہ آپ صلی اللہ علیہ وسلم قربانی دیں۔ پس آپ صلی اللہ علیہ وسلم نے فرمایا: اے عائشہ رضی اللہ عنہا! چھری لاؤ! پھر فرمایا: پتھر پر اس کو تیز کر دو تو میں نے ایسا ہی کیا، پھر آپ صلی اللہ علیہ وسلم نے چھری پکڑی، مینڈھا پکڑا اور زمین پر لٹا کر اس کو ذبح کر دیا اور فرمایا: یا اللہ! اس کو محمد صلی اللہ علیہ وسلم کی طرف سے، آل محمد کی طرف سے اور محمد صلی اللہ علیہ وسلم کی امت کی طرف سے قبول کر، یہ دعا کر کے آپ نے قربانی ذبح کر دی۔‘‘ (مسلم)","",{"k":"مسلم (1967)، ابوداؤد (2792)، احمد (23970)۔"}],[3841,"سیدنا جابر رضی اللہ عنہ نے بیان کیا کہ نبی کریم صلی اللہ علیہ وسلم نے ذبح کے دن سینگوں والے دو مینڈھے ذبح کیے، جو سفید و سیاہ رنگ کے تھے اور خصی تھے۔ چنانچہ جب ان کو کعبہ کی طرف لٹایا تو یوں کہا: میں نے اپنا چہرہ اس ذات کی طرف پھیرا جس نے آسمانوں کو اور زمین کو پیدا کیا۔ میں ملت ابراہیم پر یک سو ہو کر ذبح کرتا ہوں اور میں شرک کرنے والوں سے نہیں ہوں۔ (میری نماز میری قربانی میری زندگی اور میری موت اللہ کے لیے ہے جو سب جہانوں کو پالنے والا ہے) اس کا کوئی شریک نہیں ہے اور مجھے اس بات کا حکم دیا گیا ہے اور میں مسلمانوں میں سے ہوں۔ اے اللہ! یہ تیری طرف سے ہے اور تیرے لیے ہے۔ اے اللہ! یہ محمد صلی اللہ علیہ وسلم کی طرف سے اور اس کی امت کی طرف سے ہے: بسم اللہ واللہ اکبر۔ پھر ذبح کر دیا۔‘‘ (ابوداؤد)","",{"k":"ابوداؤد (2795)، ضعیف، البانی: 597، ترمذی (1521)، ابن ماجہ (3121)، احمد (14604)، دارمی (1946)۔"}],[3842,"اور ایک روایت میں ہے کہ فرمایا: بسم اللہ واللہ اکبر یہ میری طرف سے اور میری اُمت کے ان افراد کی طرف سے ہے جنہوں نے قربانی نہیں دی ہے۔‘‘","",{"k":"ابوداؤد (2810)، صحیح، البانی: 2436، ترمذی (1521)، ابن ماجہ (3121)، احمد (14604)، دارمی (1946)۔"}],[3843,"سیدنا ابوسعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم سینگوں والا نر مینڈھا قربانی کرتے جو سیاہ آنکھوں والا سیاہ منہ والا اور سیاہ پاؤں والا ہوتا۔ (ابوداؤد)","",{"k":"ابوداؤد (2796)، صحیح، البانی: 2426، ترمذی (2496)، نسائی (4390)، ابن ماجہ (3128)۔"}],[3844,"احمد اور بزار کی روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس سیاہ دو چتکبرے مینڈھے لائے گئے، ایک کو ذبح کرتے وقت فرمایا: یہ محمد صلی اللہ علیہ وسلم اور ان کے اہل بیت کی طرف سے ہے۔ اور دوسرے کو ذبح کرتے وقت فرمایا: یہ ان لوگوں کی طرف سے ہے جنہوں نے محمد صلی اللہ علیہ وسلم کی امت میں سے قربانی نہیں کی۔‘‘","",{"k":"بزار: 1209، واحمد باختصار ورجاله ثقات، ہیثمی: 5973۔"}],[3845,"الموصلی، الکبیر اور الاوسط کی روایت میں ہے کہ سیدنا ابو طلحہ رضی اللہ عنہ نے بیان کیا: آنحضرت صلی اللہ علیہ وسلم نے دوسرے کو ذبح کرتے وقت فرمایا: یہ اس شخص کی طرف سے ہے جو میری امت میں سے میرے اوپر ایمان لایا اور میری تصدیق کی۔‘‘","",{"k":"ابو یعلی موصلی: 1417، طبرانی کبیر، طبرانی اوسط، من رواية عبدالله بن ابى طلحة عن جده ولم يدركه ورجاله رجال الصحيح، ہیثمی: 5973۔"}],[3846,"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے سینگوں والے چتکبرے دو مینڈھے قربانی دیئے، میں نے دیکھا کہ آپ صلی اللہ علیہ وسلم نے اپنا پاؤں ان کے پہلوؤں پر رکھا بسم اللہ واللہ اکبر کہہ کر ان دونوں کو اپنے دست مبارک سے ذبح کیا۔‘‘","",{"k":"نسائی (4416)، صحیح، البانی: 4113، بخاری (7399)، مسلم (1966)، ابوداؤد (2794)، ابن ماجہ (3155)، احمد (13583)، دارمی (1945)۔"}],[3847,"سیدنا نعمان بن ابی فاطمہ رضی اللہ عنہ سے روایت ہے کہ میں نے سینگوں والا، خوبصورت آنکھوں والا مینڈھا خریدا تو اس کو دیکھ کر نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ایسا ہی مینڈھا تھا جس کو ابراہیم علیہ السلام نے ذبح کیا تھا۔ پس ایک انصاری آدمی نے کوشش کر کے رسول اللہ صلی اللہ علیہ وسلم کے لیے اس صفت کا مینڈھا خریدا، پس رسول اللہ صلی اللہ علیہ وسلم نے اس سے لے کر قربانی دی۔‘‘(الکبیر)‘‘","",{"k":"طبرانی کبیر ورجاله ثقات، ہیثمی: 5978۔"}],[3848,"سیدنا ابو موسیٰ رضی اللہ عنہ نے اپنی بیٹیوں کو حکم دیا کہ وہ اپنے ہاتھوں اپنی قربانی ذبح کریں اور خود انہوں نے قربانی کے پہلو پر قدم رکھا اور ذبح کرتے وقت تسمیہ و تکبیر کہی۔‘‘(رزین)‘‘","",{"k":"رزین۔","e":"۱۔ ثابت ہوا سینگوں والا جانور ذبح کیا جائے اور جس جانور کو قربانی کرنا ہے اس کی رنگ دلکش ہو تو بہتر ہے اور اگر تجربہ ہو تو اپنے ہاتھوں سے ذبح کرنا بہتر ہے، وگرنہ نمائندہ سے ذبح کروانے کی بھی اجازت ہے۔ ۲۔ جب ذبح کریں تو جانور پہلو کے بل لٹائیں اور پہلو پر پاؤں رکھ کر ذبح کریں۔ اور بسم اللہ اللہ اکبر پڑھ کر ذبح کریں اور چھری تیز کریں تاکہ ذبح ہونے والے جانور پر احسان ہو اور اسے تکلیف نہ ہو۔(مرعاۃ: ۲/۳۵۰)"}],[3849,"سیدنا عبداللہ ابن عمر رضی اللہ عنہ سے مروی ہے کہ آنحضرت صلی اللہ علیہ وسلم نے تین دن کے بعد قربانی کا گوشت کھانے کی ممانعت فرمائی ہے۔‘‘(مسلم)‘‘","",{"k":"مسلم (1970)، بخاری (5574)، ترمذی (1509)، نسائی (4423)، احمد (6153)، دارمی (1957)۔"}],[3850,"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں کچھ لوگ دیہات والوں سے قربانی کے اوقات میں آحاضر ہوئے۔ تو رسول اللہ صلی اللہ علیہ وسلم نے صحابہ کو حکم دیا کہ تین دن کے لیے گوشت اپنے پاس رکھو اور بقیہ صدقہ کر دو۔ جب آئندہ سال آیا تو آپ صلی اللہ علیہ وسلم سے عرض کی گئی کہ یا رسول اللہ صلی اللہ علیہ وسلم! لوگ اپنی قربانی کی کھالوں سے پانی کے لیے مشکیزے تیار کرتے ہیں اور چربی صاف کر کے رکھتے ہیں۔ فرمایا مسئلہ کیا ہے؟ عرض کی گئی: آپ صلی اللہ علیہ وسلم نے قربانی کا گوشت تین ایام سے زائد کھانے سے ممانعت فرمادی تھی۔ فرمایا میں نے اس جماعت کی وجہ سے ممانعت کی تھی جو پچھلے سال آئی تھی اب تم کھاؤ صدقہ کرو اور بچا کر رکھو۔‘‘(مسلم)‘‘","",{"k":"مسلم (1971)، بخاری (5570)، ترمذی (1511)، نسائی (4433)، ابوداؤد (2812)، ابن ماجہ (3159)، احمد (25223)، مؤطا (1047)، دارمی (1959)۔"}],[3851,"سیدہ عائشہ رضی اللہ عنہا کی ایک روایت ہے کہ ہم قربانی کے جانوروں کی پنڈلیاں سنبھال رکھتے تھے جنہیں رسول اکرم صلی اللہ علیہ وسلم عید قربان کے پندرہ دن بعد کھاتے تھے۔‘‘(ابن ماجہ)‘‘","",{"k":"ابن ماجہ (3313)، صحیح، البانی: 2678، بخاری (5438)، ترمذی (1511)، نسائی (4432)، احمد (25013)۔"}],[3852,"قاسم سے روایت ہے کہ ابن خباب نے خبر دی کہ ابو سعید نے فرمایا: میں کہیں گیا ہوا تھا، واپس پلٹا تو لوگوں نے میرے سامنے گوشت رکھ کر کہا: یہ قربانی کا گوشت ہے۔ میں نے کہا: اسے اٹھا لو میں اسے چکھوں گا بھی نہیں، چنانچہ پھر میں اٹھ کر قتادہ بن نعمان کے پاس گیا، وہ ماں کی طرف سے میرے بھائی اور بدری صحابی تھے، ان کو یہ بتایا تو انہوں نے کہا: تیرے سفر پر جانے کے بعد نئے حکم کے تحت تین ایام قربانی کا گوشت کھانے کی جو ممانعت تھی وہ تبدیل کر دی گئی ہے۔‘‘(بخاری)‘‘","",{"k":"بخاری (5568)، نسائی (4428)، احمد (26615)، مؤطا (1048)۔"}],[3853,"ایک روایت میں ہے کہ قتادہ بن نعمان کو قربانی کا گوشت پیش کیا گیا تھا تو انہوں نے کہا: کیا نبی کریم صلی اللہ علیہ وسلم نے اس سے منع نہیں کیا؟ ابو سعید نے کہا: نیا حکم آچکا ہے۔ نبی کریم صلی اللہ علیہ وسلم نے تین دن کے بعد اس کے کھانے کی ممانعت فرمائی تھی اور پھر آپ صلی اللہ علیہ وسلم نے اجازت دے دی ہے کہ ہم کھائیں اور ذخیرہ بھی کریں۔‘‘(نسائی)‘‘","",{"k":"نسائی (4428)، صحیح، البانی: 4125، مسلم (1973)، احمد (11402)، مؤطا (1048)۔"}],[3854,"نبیشہ کا بیان ہے کہ رسول اکرم صلی اللہ علیہ وسلم نے فرمایا: ہم نے قربانی کا گوشت تین دن کے بعد کھانے سے منع کیا تھا تاکہ تمہارے پاس وسعت آجائے۔ چنانچہ اللہ تعالیٰ نے اب وسعت کر دی ہے پس کھاؤ ذخیرہ کرو، ثواب کی نیت رکھو خبر دار رہو، یہ ایام کھانے پینے اور یاد الہی کے ہیں۔‘‘(ابوداؤد)‘‘","",{"k":"ابوداؤد (2813)، صحیح، البانی: 2439، نسائی (4230)، ابن ماجہ (3160)، احمد (20202)، دارمی (1958)۔","e":"ان احادیث سے پتہ چلتا ہے کہ پہلے نبی اکرم صلی اللہ علیہ وسلم نے قربانی کا گوشت تین دن سے زیادہ کھانے پر پابندی لگا دی تھی۔ جب دیکھا کہ خوشحالی ہے اب غرباء کے لیے گوشت کی وافر مقدار ہو جاتی ہے تو اب اجازت دے دی کہ فقراء پر تقسیم کر لیا جائے، دوست احباب اور رشتہ داروں کو بھی کھلایا جائے اور خود بھی رکھ لیا جائے اگرچہ ایک ماہ تک گزر جائے۔(گوندلوی)"}],[3855,"سیدہ ام سلمہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جس کے پاس ذبح کرنے کی چیز ہو اور وہ ذبح کرنے کا ارادہ رکھتا ہو تو ذوالحجہ کا چاند نظر آنے کے بعد اپنے بال اور ناخن نہ کاٹے یہاں تک کہ قربانی ذبح کر دے۔‘‘(مسلم)‘‘","",{"k":"مسلم (1977)، ترمذی (1523)، نسائی (4364)، ابوداؤد (2791)، ابن ماجہ (3150)، احمد (26114)، دارمی (1948)۔"}],[3856,"کبیرہ بنت سفیان نے رسول اللہ صلی اللہ علیہ وسلم کا یہ فرمان نقل کیا کہ: خاکستر خاکی رنگ کے جانور کا خون بہانا اللہ تعالیٰ کے ہاں دو سیاہ جانوروں کے خون بہانے سے زیادہ پسندیدہ ہے۔‘‘(الکبیر، سند ضعیف)‘‘","",{"k":"طبرانی کبیر: 25/15، وفیہ محمد بن سلیمان بن مسمول وهو ضعیف، ہیثمی: 5944۔"}],[3857,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ایک سال کا دنبہ بڑے بکرے سے زیادہ بہتر ہے۔ داؤد نے کہا: اس حدیث میں لفظ سید بمعنی جلیل ہے۔‘‘(احمد سند مخفی ہے)‘‘","",{"k":"احمد (8974)، وفیہ ابو ثقال قال البخاری فیہ نظر، ہیثمی: 5945۔","e":"۱۔ بعض نے اس جملہ سے کہ تم میں سے کوئی قربانی کرنا چاہتا ہو، ثابت کیا ہے کہ قربانی واجب نہیں کیونکہ مرضی پر چھوڑا گیا ہے، مگر یہ اجتہاد غلط ہے۔ کیونکہ اوپر گزر چکا ہے اگر طاقت ہو تو قربانی واجب ہے۔ ۲۔ اس میں دلیل ہے کہ اگر قربانی کا عزم ہے اور ذوالحجہ کا پہلا دھاکا شروع ہو چکا ہو تو بال اور ناخن وغیرہ بھی نہ ترشوائے جائیں، تاکہ احرام والوں سے مشابہت بھی ہو جائے اور قربانی دوزخ سے نجات کا ذریعہ ہے، سارے جسم کے بال بھی دوزخ سے آزاد ہو جائیں۔(مرعاۃ: ۲/۳۵۶)"}],[3858,"سیدنا عدی بن حاتم رضی اللہ عنہ کہتے ہیں: میں نے عرض کیا یا رسول اللہ! میں اپنا کتا بسم اللہ پڑھ کر چھوڑتا ہوں، اس کے متعلق کیا حکم ہے؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جب تو اپنا کتا چھوڑتا اور بسم اللہ کہتا ہے تو اگر وہ شکار کو پکڑ کر مار ڈالے اور اس میں سے کچھ کھائے تو اس شکار کو تو نہ کھا، اس لیے کہ اس نے اپنے لیے شکار کیا ہے۔ میں نے عرض کیا: جب میں اپنا کتا چھوڑتا ہوں تو اس کے ساتھ دوسرا کتا میں پاتا ہوں اور مجھے معلوم نہیں ہوتا کہ ان میں سے شکار کس نے پکڑا ہے؟ فرمایا: اس کو نہ کھا اس لیے کہ تو نے صرف اپنے کتے پر بسم اللہ کہی ہے، غیر پر نہیں کہی ہے۔ پھر میں نے چوڑی چیز کے ساتھ شکار مارنے کے بارے میں سوال کیا۔ تو فرمایا: جب تیر چیز سے شکار ہو تو اس کو کھا اور اگر چوڑائی کی جانب سے ضرب لگ کر مر جائے تو اسے نہ کھا کیونکہ وہ مردار ہے۔‘‘(بخاری)‘‘","",{"k":"بخاری (5486)، مسلم (1929)، ترمذی (1471)، نسائی (4275)، ابوداؤد (2854)، ابن ماجہ (3215)، احمد (18889)، دارمی (2002)۔"}],[3859,"ایک روایت میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جب تو نے کتا چھوڑا اور بسم اللہ پڑھ لی اور اس نے شکار مارا اور اس میں سے کچھ نہ کھایا تو تم اسے کھا سکتے ہو اور اگر کتا شکار کھا لے تو بقیہ حصہ مت کھاؤ کیونکہ یہ اس نے اپنے لیے شکار کیا ہے۔ اور اگر اس کے ساتھ دوسرے کتے شامل ہو جائیں جن پر بسم اللہ نہیں پڑھی گئی اور وہ اس کو مار کر بچھا رکھیں تو اس کو نہ کھا اس لیے کہ تو نہیں جانتا کہ شکار کس کتے نے مارا ہے؟ اگر تم نے شکار کو تیر مارا اور پھر شکار تجھے ایک دن یا دو دن بعد ملا تو اگر اس میں تیرے تیر کے علاوہ کسی چیز کا اثر تجھے نظر نہ آئے تو اس کو کھا اور اگر وہ پانی میں گرا ہے تو اس کو نہ کھاؤ۔‘‘ (بخاری)","",{"k":"بخاری (2854)، مسلم (1929)، ترمذی (1471)، نسائی (4275)، ابوداؤد (2854)، ابن ماجہ (3215)، احمد (18889)، دارمی (2002)۔"}],[3860,"’’ابو ادریس عائد اللہ نے کہا، میں نے ابو ثعلبہ خشنی سے سنا، انہوں نے کہا: میں رسول اکرم صلی اللہ علیہ وسلم کی خدمت اقدس میں حاضر ہوا اور پوچھا: ہم اہل کتاب کے ملک میں رہتے ہیں اور ان کے برتنوں میں کھاتے ہیں نیز وہ علاقہ شکار کا ہے میں اپنے کمان، سدھائے ہوئے کتے اور غیر سدھائے ہوئے کتے کے ساتھ شکار کرتا ہوں۔ مجھے بتائیں میرے لیے حلال کون سی چیز ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: تم نے جو یہ بتایا ہے کہ تم اہل کتاب کے علاقہ میں ہونے کی وجہ سے ان کے برتنوں میں کھاتے ہو، اس کے متعلق سنو: اگر تمہیں دوسرے برتن میسر آئیں تو ان میں کھاؤ اور اگر نہ ملیں تو پھر ان کے برتنوں کو دھو کر استعمال کر سکتے ہو۔ تم نے یہ بھی کہا کہ تم شکار کے علاقہ میں رہتے ہو یاد رکھو! جو شکار تم اپنے کمان اور تیر سے کرو تو اس پر اللہ کا نام لیا کرو پھر تم کھا سکتے ہو، اور جو شکار تم سدھائے ہوئے کتے سے کرو اس پر بھی اللہ کا نام لیا کرو پھر تم کھا سکتے ہو، اور جو غیر سدھائے ہوئے کتے سے شکار کرو تو اگر تم نے اس کا ذبح کرنا پا لیا (یعنی اس کی جان نکلنے سے پہلے پہلے تم نے ذبح کر لیا) تو اسے بھی تم کھا سکتے ہو۔‘‘ (بخاری)","",{"k":"بخاری (5488)، مسلم (1930)، ترمذی (1897)، نسائی (4266)، ابوداؤد (3839)، ابن ماجه (3211)، احمد (7293)، دارمی (2499)۔"}],[3861,"’’ایک روایت میں ہے، فرمایا: اگر تیرے پاس سکھائے کتے ہیں تو وہ جو تیرے پاس لائیں اس کو کھاؤ خواہ تم نے ذبح کیا ہو یا نہ کیا ہو۔ عرض کیا: اس میں سے کچھ حصہ کتے نے کھایا ہو تب بھی؟ فرمایا: خواہ اس سے کھایا ہو۔‘‘ (ابو داؤد)","",{"k":"ابوداؤد (2857)، حسن، البانی: 2482، لکن قوله وان اكل منه منكر، بخاری (5496)، مسلم (1931)، ترمذی (1797)، نسائی (4266)، ابن ماجه (3207)، احمد (17293)، دارمی (2499)۔"}],[3862,"’’دوسری روایت ہے۔ جب تو شکار کو تیر مارے اور شکار تجھے تین دن بعد ملے اور تیرا تیر اس میں موجود ہو تو اس کو کھاؤ جب تک بد بو پیدا نہ ہو۔‘‘ (ابو داؤد)","",{"k":"ابوداؤد (2861)، صحیح، البانی: 2487، مسلم (1931)، نسائی (4303)، احمد (17284)۔"}],[3863,"’’ایک روایت میں کتے کے متعلق فرمایا: تین دن کے بعد شکار ملے تو اس کو کھاؤ، مگر بد بو دار ہو جائے تو اس کو ترک کر دو۔‘‘ (مسلم)","",{"k":"بخاری (5496)، مسلم (1931)، ترمذی (1797)، نسائی (4303)، ابوداؤد (2861)، ابن ماجه (3207)، احمد (17293)۔"}],[3864,"’’امام مالک کو سعد بن ابی وقاص رضی اللہ عنہ کے حوالے سے روایت پہنچی ہے کہ ان سے سکھائے ہوئے کتے کے بارے میں سوال کیا گیا، جب وہ شکار کو مار دے تو انہوں نے کہا: اس کو کھاؤ خواہ اس میں سے ایک ہی ٹکڑا رہ گیا ہو۔‘‘ (مالک)","",{"k":"مؤطا (1090)۔","e":"۱۔ ثابت ہوا سدھائے ہوئے کتے کے ذریعہ شکار کرنا حلال ہے اور تیر کے ذریعے شکار کرنا بھی جائز ہے۔ ۲۔ ثابت ہوا کتا چھوڑتے ہوئے اور تیر چلاتے ہوئے بسم اللہ پڑھنا واجب وضروری ہے، تب شکار حلال ہوگا۔ اگر کتا بغیر بسم اللہ پڑھے خود ہی مالک کے کہنے سے پہلے ہی شکار پر جھپٹ پڑے تو بھی شکار حلال نہیں۔ اور یہ بھی ثابت ہوا شکاری جب شکار کو زندہ پائے تو اسے ذبح کرے، اگر مردہ پائے تو بھی کھا سکتا ہے۔ بشرطیکہ کتے نے شکار کر کے کاٹا نہ ہو، یعنی کھایا نہ ہو، اگر کھایا ہو تو پھر شکار کھانا حرام ہے اور کتے کے ساتھ شکار میں دوسرے کتے بھی مل جائیں تو بھی شکار نہ کھایا جائے۔ اگر شکار زندہ ہو تو دوسرے کتے بھی مل جائیں تو بھی شکار نہ کھایا جائے، اگر شکار زندہ ہو تو دوسرے کتے ملے بھی ہوں پھر بھی ذبح کر کے اسے کھانا حلال ہے۔ ۳۔ یہ بھی ثابت ہوا جب شکار تیر کے ذریعہ کیا جائے تو وہ مردہ بھی پایا جائے تو اسے کھانا حلال ہے، اور جب شکار پر تیر پھینکا ہو اور شکار نظروں سے اوجھل ہو جائے اور ایک دن کے بعد شکاری اسے پاتا ہے اسی تیر کا اس میں نشان ہے اور کوئی اثر نہیں تو اسے کھانا بھی حلال ہے۔ ہاں اگر وہ پانی میں غرق ہو چکا ہو تو پھر نہ کھائے ہو سکتا ہے وہ پانی میں غرق ہو کر مرا ہے۔ (تفہیم الاسلام: ۲/۷۳۴) شکار غیب ہو گیا ہو تین دن تک مل جائے تو حلال ہے اگر بد بو چھوڑ جائے تو پھر حلال نہیں، خواہ تین دن سے پہلے ملے یا بعد میں ملے۔"}],[3865,"’’سیدنا عبد اللہ بن مغفل رضی اللہ عنہ بیان کرتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے کنکر مارنے سے منع کیا اور فرمایا: اس سے نہ تو شکار کیا جا سکتا ہے اور نہ ہی دشمن کو زخمی کر کے مارا جا سکتا ہے۔ البتہ اس سے آنکھ ضائع ہو جاتی ہے اور دانت ٹوٹ جاتا ہے۔‘‘ (بخاری)","",{"k":"بخاری (6220)، مسلم (1954)، نسائی (4815)، ابوداؤد (5270)، ابن ماجه (3227)، احمد (20050)، دارمی (440)۔","e":"۱۔ اس کا پس منظر یہ ہے کہ سیدنا عبد اللہ رضی اللہ عنہ نے ایک آدمی کو دیکھا وہ کنکریاں پھینک رہا ہے، انہوں نے اسے بتایا کہ رسول اکرم صلی اللہ علیہ وسلم نے ایسی فضول حرکت سے منع فرمایا ہے، اس کے بعد بھی اس نے یہ کام نہ چھوڑا، تو فرمایا: میں نے تجھے اس بارے میں رسول اکرم صلی اللہ علیہ وسلم کا فرمان بھی سنایا ہے تو پھر بھی باز نہیں آتا۔ میں تجھ سے کلام نہ کروں گا۔ ۲۔ اس حدیث سے ثابت ہوا کہ جانور کو خواہ مخواہ تکلیف پہنچانا حرام ہے، کنکری مارنے سے جانور کا شکار تو نہیں ہوگا، لیکن اس کے دانت یا آنکھ کو نقصان پہنچ جائے گا۔ اس سے شکاری کو کیا فائدہ ہوگا؟ اس طرح کا کھیل عبث ہے اور اس طرح چوٹ لگنے سے اگر جانور مر جائے تو اس کا کھانا حلال نہیں۔ ۳۔ ثابت ہوا کسی پرندہ یا شکار کو بغیر ضرورت کے شکار کے لیے سنگباری نہ کی جائے۔ اور لوگوں کو اذیت پہچانے سے گریز کیا جائے۔ اور دشمن سے لڑائی کے لیے عمدہ قسم کا اسلحہ رکھا جائے نکما اسلحہ رکھنا جائز نہیں۔ (تفہیم الاسلام: ۲/۷۳۸)"}],[3866,"’’سیدنا جابر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے مجوسی کے کتے کے شکار کو کھانے سے منع فرمایا ہے۔‘‘ (الترمذی)","",{"k":"ترمذی (1466)، ضعیف، البانی: 247، ابن ماجه (3209)۔"}],[3867,"’’سیدنا جابر بن عبد اللہ رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں غزوے پر روانہ کیا اور ہم تعداد میں تین سو سوار تھے، اور ہمارے امیر ابو عبیدہ تھے۔ ہم قریش کے تجارتی قافلے کی گھات میں لگے تھے۔ ہم لوگ سمندر کے ساحل پر نصف مہینے تک رہے۔ ہمیں شدید بھوک کا سامنا کرنا پڑا یہاں تک ہم نے درختوں کے پتے کھائے اور غزوے کا نام جیش الخبط پڑ گیا۔ ان حالات میں سمندر نے ہماری سمت میں ایک سمندری حیوان پھینک دیا اس کو عنبر کہا جاتا تھا۔ پس ہم نے نصف مہینے تک اسے کھایا اور اس کی چربی سے تیل حاصل کیا، یہاں تک کہ ہمارے جسم موٹے تازے ہو گئے۔ سیدنا ابو عبیدہ رضی اللہ عنہ نے اس کی پسلیوں میں سے ایک پسلی کھڑی کرا دی، پھر بلند قامت آدمی فوج میں سے دیکھا اور اونٹوں میں طویل اونٹ دیکھا۔ آدمی کو اس پر سوار کیا تو وہ مچھلی کی پسلی کے نیچے سے گزر گیا۔ اس کی آنکھ کے خول میں چند آدمی بیٹھے اس کی آنکھ میں ہم نے اتنے اتنے منکے چربی نکالی۔ ابتدا میں ہمارا زاد راہ صرف کھجوریں تھیں جو ایک بوری میں تھیں۔ سیدنا ابو عبیدہ رضی اللہ عنہ ہر آدمی کو مٹھی بھر کر دیتے تھے۔ پھر ایک وقت آیا تو ایک ایک کھجور دینے لگے، جب وہ بھی ختم ہو گئیں تو ان کے مفقود ہونے کا ہمیں احساس ہوا۔‘‘ (مسلم)","",{"k":"مسلم (1935)، بخاری (5243)، ترمذی (2475)، نسائی (4354)، ابوداؤد (3840)، ابن ماجه (4159)، احمد (14629)، مؤطا (1730)، دارمی (2012)۔"}],[3868,"’’سیدنا جابر رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں غزوے پر روانہ کیا اور سیدنا ابو عبیدہ رضی اللہ عنہ کو ہم پر امیر مقرر کیا تاکہ ہم قریش کا تجارتی قافلہ پکڑیں اور ایک بوری کھجور ہمیں زاد راہ دیا، اس کے علاوہ آپ صلی اللہ علیہ وسلم کو کچھ میسر نہ تھا۔ پس سیدنا ابو عبیدہ رضی اللہ عنہ ہمیں ایک ایک کھجور دیا کرتے تھے۔ مثل حدیث سابق اور اس میں یہ بھی ہے کہ ہمیں ساحل سمندر پر ریت کے موٹے تودے کی طرح کوئی چیز نظر آئی، ہم اس کے پاس گئے وہ ایک حیوان تھا جس کو عنبر کہا جاتا ہے۔ پہلے تو سیدنا ابو عبیدہ رضی اللہ عنہ نے کہا: یہ مردار ہے۔ پھر انہوں نے کہا: نہیں، بلکہ ہم رسول اللہ صلی اللہ علیہ وسلم کے قاصد ہیں اور اللہ تعالیٰ کی راہ میں چل رہے ہیں اور تم اضطراری حالت میں ہو تم اس کو کھاؤ، ہم نے اس پر ایک مہینہ بسر کیا اور ہماری تعداد تین سو تھی اور ہم لوگ موٹے تازے ہو گئے، اور اس کی آنکھ سے ہم نے کئی منکے چربی نکالے، اور اپنے رفقاء کو دیکھا ہم اس سے بیل جیسے بڑے بڑے گوشت کے ٹکڑے کاٹتے تھے۔ ابو عبیدہ نے ہم میں سے تیرہ مرد اس کی آنکھ کے خول میں بیٹھائے۔ اس روایت میں یہ بھی ہے اور ہم نے اس کے گوشت کے بڑے بڑے ٹکڑے کاٹ کر زاد راہ بنایا۔ جب ہم مدینہ منورہ میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور آپ صلی اللہ علیہ وسلم سے اس کا تذکرہ کیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: وہ اللہ تعالیٰ نے تمہارے لیے رزق نکالا تھا اگر تمہارے پاس اس کے گوشت میں سے کچھ باقی ہے تو ہمیں کھلاؤ۔ ہم نے آپ صلی اللہ علیہ وسلم کو دیا تو آپ صلی اللہ علیہ وسلم نے اس کو کھایا۔‘‘ (مسلم)","",{"k":"مسلم (1935)، بخاری (2483)، نسائی (4354)، ابوداؤد (3840)، ابن ماجه (4159)۔"}],[3869,"’’اور ان روایات میں سے ایک میں اس طرح کا بیان ہے کہ ایک آدمی نے تین اونٹ ذبح کیے، پھر بھوک لگی تو تین اونٹ ذبح کیے اور پھر بھوکے ہوئے تو پھر تین اونٹ ذبح کیے۔ اس کے بعد اس کو ابو عبیدہ رضی اللہ عنہ نے منع کر دیا۔‘‘ (نسائی)","",{"k":"نسائی (4352)، صحیح، البانی: 4059، بخاری (2483)، مسلم (1935)، ترمذی (2475)، ابن ماجه (4159)، احمد (13926)، مؤطا (1730)، دارمی (2012)۔","e":"۱۔ سیدنا ابو عبیدہ رضی اللہ عنہ نے پہلے تو بذریعہ اجتہاد پابندی لگا دی کہ یہ مردار ہے اور مردار حرام ہے لہذا یہ مچھلی نہ کھائیں۔ پھر خود ہی مزید اجتہاد کیا کہ اللہ تعالیٰ نے مجبوری کے تحت مردار حلال قرار دیا ہے۔ اگر چہ یہ مردار ہے تم مجبور ہو تمہارے لیے یہ حلال ہے۔ حالانکہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا تھا، سمندر کا پانی پاک ہے اور اس کا مردار حلال ہے۔ (بلوغ المرام) اس کی رو سے یہ مچھلی حلال تھی، نبی اکرم صلی اللہ علیہ وسلم نے صحابہ کرام رضی اللہ عنہم کی دلجوئی کے پیش نظر فرمایا تھا، اس کا حصہ تمہارے پاس ہے؟ انہوں نے کہا ہے، تو نبی اکرم صلی اللہ علیہ وسلم نے تبرک کے طور پر اللہ کی نعمت کے تصور سے اسے کھایا۔ ۲۔ یہ بھی ثابت ہوا سمندر کا جانور حلال ہے، خصوصاً مچھلی خواہ یہ زندہ ہو یا مردہ ہو۔ (عون المعبود: ۳/۴۲۸)"}],[3870,"’’سیدنا جابر بن عبد اللہ رضی اللہ عنہ نے کہا کہ ہمیں رسول اللہ صلی اللہ علیہ وسلم نے روانہ کیا اور ہم تین سو تھے اور اپنا سامان سفر اپنی گردن پر اٹھایا ہوا تھا۔‘‘ (مسلم)","",{"k":"مسلم (1935)، بخاری (5243)، ابوداؤد (3840)، احمد (14629)، مؤطا (1730)، دارمی (2012)۔"}],[3871,"’’ایک روایت میں ہے کہ آنحضرت صلی اللہ علیہ وسلم نے تین سو افراد پر مشتمل ایک فوجی دستہ روانہ کیا اور ان پر ابو عبیدہ رضی اللہ عنہ کو امیر متعین کیا، ان کی خوراک ختم ہو گئی، تو ابو عبیدہ رضی اللہ عنہ نے سب سے لے کر خوردنی اشیاء ایک بوری میں جمع کر لیں، وہ خود ہم پر خوراک تقسیم کرتے، یہاں تک کہ ہمیں ایک دن کی خوراک ایک کھجور دی جاتی تھی۔‘‘","",{"k":"مسلم (1935)، بخاری (5243)، ابوداؤد (3840)، احمد (14629)، مؤطا (1730)، دارمی (2012)۔"}],[3872,"’’ایک میں یہ بات ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ساحل سمندر کی طرف ایک فوجی دستہ روانہ کیا اور میں اس میں شامل تھا۔ مثل احادیث سابقہ اس میں یہ بیان ہے کہ فوج نے اس مچھلی سے اٹھارہ رات تک گوشت کھایا۔‘‘","",{"k":"مسلم (1935)، بخاری (5243)، ابوداؤد (3840)، احمد (14629)، مؤطا (1730)، دارمی (2012)۔"}],[3873,"’’ایک روایت میں ہے۔ آپ نے جہینہ کی طرف لشکر روانہ کیا تھا آگے سابقہ احادیث کی مثل ہی واقعہ بیان کیا۔‘‘ (مسلم)","",{"k":"مسلم (1935) -"}],[3874,"’’ایک روایت میں ہے۔ ہمارا زاد راہ ختم ہوا تو سیدنا ابو عبیدہ رضی اللہ عنہ نے فوج کی خوراک یک جا کرنے کا حکم دیا تو انہیں جمع کیا گیا جس سے دو تھیلے کھجور کے بھر گئے۔‘‘ (اس سے آگے پہلے کی طرح حدیث ذکر کی) (بخاری)","",{"k":"مسلم (1935)، بخاری (4360)، ترمذی (2475)، نسائی (4354)، ابن ماجه (4159)، احمد (14629)، مؤطا (1730)، دارمی (2012)۔"}],[3875,"’’ان روایات میں سے ایک یہ ہے کہ قیس بن سعد رضی اللہ عنہ نے اپنے والد کو حالات بتائے اور کہا: میں اس لشکر میں موجود تھا اور لوگ بھوکے تھے تو انہوں نے کہا: اونٹ ذبح کر، تو قیس نے کہا: میں نے ذبح کیے تھے۔ پھر وہ بھوکے ہوئے تو انہوں نے کہا: اونٹ ذبح کر، تو انہوں نے کہا: میں نے ذبح کیے۔ پھر لوگ بھوکے ہوئے تو انہوں نے کہا: اونٹ ذبح کر، انہوں نے کہا: میں نے ذبح کیے تھے۔ پھر لوگ فاقے میں مبتلا ہوئے۔ انہوں نے کہا: اونٹ ذبح کر، تو انہوں نے کہا: اس مرتبہ مجھے منع کر دیا گیا۔‘‘","",{"k":"مسلم (1935)، بخاری (4360)، ترمذی (2475)، نسائی (4354)، ابن ماجه (4159)، احمد (14629)، مؤطا (1730)، دارمی (2012)۔"}],[3876,"’’سیدنا جابر بن عبد اللہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: سمندر جو کچھ نکال پھینکے یا جس سے سکڑ جائے تو اس کو کھاؤ اور جو سمندر میں مر کر تیرنے لگے تو اس کو نہ کھاؤ۔‘‘ (اور یہ روایت ابو داؤد میں موقوف منقول ہوئی ہے)","",{"k":"ابوداؤد (3815)، ضعیف: 821، ابن ماجه (3247)۔","e":"صحیح حدیث میں گزرا ہے کہ مچھلی زندہ ہو یا مردہ ہو حلال ہے، یہ قید بے حیثیت ہے۔ (گوندلوی)"}],[3877,"’’سعد الجاری مولی عمر رضی اللہ عنہ سے روایت ہے کہ میں نے سیدنا ابن عمر رضی اللہ عنہ سے سوال کیا کہ مچھلیاں جب ایک دوسرے کو مار دیتی ہیں یا سردی سے مر جاتی ہیں تو انہیں کھا سکتا ہوں؟ انہوں نے کہا: ان کو کھانے میں کوئی حرج نہیں ہے۔ پھر میں نے سیدنا عبد اللہ بن عمرو بن العاص رضی اللہ عنہ سے سوال کیا، تو انہوں نے بھی اس کی مثل جواب دیا۔‘‘ (مالک)","",{"k":"مؤطا (1072)۔","e":"اس میں بھی دلیل ہے کہ صحابہ کرام رضی اللہ عنہم بھی مردہ مچھلی کو حلال تصور کرتے تھے۔ (شرح زرقانی: ۸۹/۳)"}],[3878,"’’سیدنا ابن عمر رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: شکاری یا مویشی کے محافظ کتے کے علاوہ کوئی کتا جس نے گھر میں رکھا تو اس کے اعمال کے اجر میں سے ہر دن دو قیراط کم کر دیئے جاتے ہیں۔‘‘ (ترمذی)","",{"k":"ترمذی (1487)، صحیح، البانی: 1202، بخاری (5482)، مسلم (1574)، نسائی (4291)، احمد (6407)، مؤطا (1808)، دارمی (2004)۔"}],[3879,"’’سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اکرم صلی اللہ علیہ وسلم نے فرمایا: جس نے جانوروں کی رکھوالی شکاری اور کھیتی باڑی کے علاوہ کتا رکھا تو ہر دن اس کے اجر و ثواب سے ایک قیراط کم کیا جاتا ہے۔‘‘ (ترمذی)","",{"k":"ترمذی (1489)، صحیح، البانی: 1204، بخاری (3324)، مسلم (1576)، ابوداؤد (2461)، ابن ماجه (3195)، احمد (9209)۔"}],[3880,"’’سیدنا ابو ہریرہ رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جس نے کتا رکھا جو نہ کھیت میں رکھنے والا ہو، نہ شکاری ہو، اور نہ ہی جانوروں کے لیے ہو تو اس کے اعمال میں سے ایک قیراط کے برابر اجر ہر دن کم کیا جاتا ہے۔‘‘ اس حدیث کے ایک راوی سلیم نے کہا: میرے گمان میں انہوں نے قیراط کے متعلق فرمایا ہے کہ وہ احد پہاڑ جتنا ہوتا ہے۔ (احمد)","",{"k":"احمد (8342)، مسلم (1575)، ترمذی (1489)، نسائی (4290)، ابوداؤد (2844)، ابن ماجه (3204)۔"}],[3881,"’’ایک روایت میں ہے جس نے کتا پال رکھا جو نہ تو مویشیوں کے لیے ہو نہ شکاری ہو اور نہ وہ زراعت کے لیے ہو تو اس کے اجر سے ہر دن ایک قیراط اجر کم کیا جاتا ہے۔ زہری نے کہا: اس حدیث کا تذکرہ سیدنا عبد اللہ ابن عمر رضی اللہ عنہ سے کیا گیا تو انہوں نے کہا: ’’اللہ تعالیٰ ابو ہریرہ رضی اللہ عنہ پر رحمت فرمائے۔‘‘ وہ خود بھی صاحب زراعت تھے۔‘‘"],[3882,"’’ایک روایت میں دو قیراط کا ذکر ہے۔‘‘ (بخاری)","",{"k":"بخاری (5480)، مسلم (1574)، ترمذی (1487)، نسائی (4291)، احمد (6407)، مؤطا (1808)، دارمی (2004)۔","e":"۱۔ قیراط احد پہاڑ کے وزن کے برابر بھی آتا ہے وہ جنازہ کے لیے ہے۔ مگر یہاں یہ مراد نہیں، یہاں ایک چیز کے چوبیس حصے کریں تو ایک کو کہتے ہیں، آج کل اس کا وزن گندم کے چار دانوں کے برابر قرار دیا جا سکتا ہے۔ اور ایک حدیث میں ایک قیراط وزن کم ہونے کا آتا ہے، ایک میں دو قیراط آتا ہے، اس کا حل یہ ہے کہ یہ مختلف حالات کے مطابق ہے، ایک حالت کی سنگینی میں دو قیراط کم ہوتا ہے، کسی حالت میں ثواب ایک قیراط کم ہوتا ہے۔ ۲۔ ان سے ثابت ہوا مویشیوں یا زراعت کی دیکھ بھال کرنے والے کتے اور شکاری کتے اس میں گھر کی دیکھ بھال والے کتے بھی رکھ سکتے ہیں۔ ان کے سوا فضول شوق کی تسکین کے لیے کتا رکھنا منع اور حرام ہے۔ کیونکہ لوگ اس سے خوفزدہ ہوتے ہیں اور فرشتے وہاں داخل نہیں ہوتے جہاں کتا ہو اور اس میں نجاست اور گندہ پن بھی بہت زیادہ ہے اس لیے منع کیا ہے۔\n۳۔ اصل میں کتا کوئی بھی اچھا نہیں مگر شریعت نے آسانی کے لیے زراعت اور حفاظت اور شکار کے لیے اس کی اجازت دے دی ہے۔ تاہم اس کے باوجود اگر یہ کسی برتن میں منہ ڈالے گا تو اسے ایک مرتبہ مٹی کے ساتھ اور سات مرتبہ پانی کے ساتھ ہی دھویا جائے گا۔ اور کوئی بھی کتا ہو شکاری یا حفاظتی ہو اسے فروخت کرنا حرام ہے۔ (تفہیم الاسلام: ۷۳۲/۲)"}],[3883,"’’عمرو بن شرید نے کہا، میں نے اپنے والد شرید کو رسول اکرم صلی اللہ علیہ وسلم کا یہ فرمان بیان کرتے ہوئے سنا کہ جس نے بلا ضرورت ایک چڑیا مار ڈالی تو وہ قیامت کے دن اس پر آواز دے گی اور کہے گی: اے میرے رب! فلاں شخص نے مجھے ضرورت کے بغیر قتل کیا تھا اور مجھے فائدے کے لیے نہیں مارا تھا۔‘‘ (النسائی)","",{"k":"نسائی (4446)، ضعیف، البانی: 303، احمد (18976)۔","e":"اگر چہ اسے ضعیف کہا گیا ہے، شریعت نے بے جا جانور یا پرندہ کو اذیت دینے اور فضول حرکت کرنے سے منع کیا ہے، اس کا تقاضا ہے کہ چڑیا پر یہ ستم نہ کیا جائے۔ (گوندلوی)"}],[3884,"’’سیدنا شداد بن اوس رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے دو باتیں یاد کی ہیں آپ صلی اللہ علیہ وسلم نے فرمایا: اللہ تعالیٰ نے ہر چیز کے لیے احسان اور حسن سلوک لکھ دیا ہے۔ جب تم قتل کرو، تو بہتر طریقے سے قتل کرو، اور جانور ذبح کرو تو بہتر طریقے سے ذبح کرو اور تم میں سے ذبح کرنے والا اپنی چھری تیز کرے، اور اپنے ذبیحہ کو آرام پہنچائے۔‘‘ (مسلم)","",{"k":"مسلم (1955)، ترمذی (1409)، نسائی (4414)، ابوداؤد (2815)، ابن ماجه (3170)، احمد (16689)، دارمی (1970)۔"}],[3885,"’’سیدنا عبد اللہ ابن عمر رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے چھریاں تیز کرنے کا حکم دیا ہے، اور یہ حکم دیا ہے کہ چھری چوپائیوں سے مخفی رکھی جائے۔ فرمایا: جب کوئی تم میں سے ذبح کرنے لگے تو جلدی سے ذبح کر دے۔‘‘ (ابن ماجہ)","",{"k":"ابن ماجه (3172)، ضعیف، البانی: 682، احمد (18976)۔","e":"یہ رحمت الہی ہے کہ تمام مخلوقات پر چھائی ہے، خواہ انسان ہو، حیوان ہو، ہر ذی روح پر اس محسن حقیقی کی مہربانی اور فضل واحسان عام ہے۔ ۲۔ قتل کرنے میں احسان یہ ہے کہ مثلہ نہ کیا جائے، کند آلہ سے نہ مارا جائے۔ یہ اس وقت ہے جب کافروں سے جنگ ہو یا کوئی قتل کی صورت ہو۔ اگر قصاص کا معاملہ ہے تو پھر قصاص میں وہی طریقہ ہوگا جو قاتل نے اپنایا تھا اور اذیت دے دے کر قتل نہ کیا جائے۔ ۳۔ ذبیحہ میں احسان یہ ہے کہ جانور کند آلہ سے ذبح نہ کیا جائے، چھری تیز رکھی جائے، اور جانور زیادہ دیر لٹائے نہ رکھا جائے۔ اور جانور پر یہ بھی احسان ہے جب ایک جانور کو ذبح کرے تو دوسرا اسے دیکھ نہ رہا ہو کیونکہ اس سے اسے تکلیف پہنچتی ہے۔ یہ بھی جانور کے ساتھ احسان ہے کہ اس کی روح ابھی باقی ہو تو اس کی گردن نہ توڑی جائے اور نہ ہی اس کی کھال اتاری جائے، نہ اعضاء کاٹے جائیں، جب تک کہ مکمل روح نہ نکل جائے۔ آج قصاب عید اور غیر عید کے موقع پر ان ہدایات کی خلاف ورزی کرتے ہیں انہیں آگاہ ہونا چاہیے۔ جانور کو بجلی یا کسی جھٹکے کے ذریعے بے ہوش کر کے اسے بے حس و حرکت کر کے ذبح کرنا بھی اذیت میں داخل ہے۔ اور بری طرح ذبح کرنا ہے۔ (تفہیم الاسلام: ۲/۷۴۲)"}],[3886,"سیدنا عبداللہ ابن عباس رضی اللہ عنہ بیان کرتے ہیں: جو شخص بسم اللہ پڑھنا بھول جائے تو کوئی حرج نہیں ہے اور جس نے جان بوجھ کر ترک کی تو وہ ذبیحہ نہ کھایا جائے۔‘‘ (رزین)","",{"k":"رزین۔","e":"صحیح موقف یہی ہے کہ قصداً بسم اللہ ذبیحہ پر نہ پڑھی جائے تو اس کا گوشت کھانا جائز نہیں، اگر بھول کر نہ پڑھی جائے تو پھر اس کی فرضیت نہیں رہتی گوشت کھا سکتے ہیں۔ اس کی تائید اس آیہ مبارکہ سے بھی ہوتی ہے:\n﴿ رَبَّنَا لَا تُؤَاخِذْنَا إِن نَّسِينَا أَوْ أَخْطَأْنَا ﴾ [البقرة: ۲۸۶]\n’’اے ہمارے رب! اگر ہم بھول جائیں یا خطا کریں تو ہمیں نہ پکڑنا۔‘‘ (تفہیم الاسلام: ۲/۷۴۳)"}],[3887,"سیدنا عبداللہ ابن عمر رضی اللہ عنہ کا بیان ہے کہ رسول اکرم صلی اللہ علیہ وسلم نے فرمایا: نے فرمایا: جو انسان کوئی چڑیا یا اس سے اوپر کوئی چیز حق کے بغیر قتل کرتا ہے تو اس سے اللہ تعالیٰ سوال کرے گا۔ عرض کیا گیا: یا رسول اللہ صلی اللہ علیہ وسلم! اس کا حق کیا ہے؟ فرمایا: کر کے اسے کھا لے اور اس کا سر کاٹ کر نہ پھینکا جائے۔‘‘ (النسائی)","",{"k":"نسائی (4445)، ضعیف، البانی: 302۔ احمد (6921)۔"}],[3888,"سیدنا ابو واقد رضی اللہ عنہ بیان کرتے ہیں کہ جب رسول اللہ صلی اللہ علیہ وسلم مدینہ منورہ تشریف لائے تو یہاں لوگ زندہ اونٹ کی کوہان کاٹ کر گوشت کھاتے اور دنبے کی چکیاں کاٹتے اور کھاتے تھے آپ صلی اللہ علیہ وسلم نے فرمایا: جس چوپائے کا کوئی حصہ کاٹا جائے جب وہ زندہ ہو تو کاٹا گیا حصہ میتہ (مردار) ہوگا۔‘‘ (ترمذی)","",{"k":"ترمذی (1480)، صحیح، البانی: 1197، ابوداؤد (2858)۔","e":"اس طرح جانور کو اذیت پہنچتی ہے۔ آپ صلی اللہ علیہ وسلم نے اس بے رحم عمل سے سختی سے منع کیا ہے۔ اور اسے حرام اور مردار قرار دیا ہے۔ اس سے ثابت ہوا کہ اس طرح کا کاٹا ہوا گوشت پلید ہے، اگر پانی میں گر جائے تو یہ پانی کو پلید کر دیتا ہے۔ (تفہیم الاسلام: ۱/۴۵)"}],[3889,"ابو العشراء رضی اللہ عنہ اپنے باپ سے روایت کرتے ہیں، اس نے کہا: میں نے عرض کیا: یا رسول اللہ صلی اللہ علیہ وسلم! کیا ذبح کرنے کا مقام گلا یا حلق ہی ہے؟ فرمایا: اگر تو نے حیوان کی ران میں نیزہ مارا تو یہ بھی تجھے کفایت کر جائے گا۔‘‘ (ابوداؤد)","",{"k":"ابو داؤد (2825)، منکر، البانی: 604، ترمذی (1481)، نسائی (4408)، ابن ماجہ (3184)، احمد (18468)، دارمی (1972)۔"}],[3890,"سیدنا عبداللہ ابن عباس رضی اللہ عنہ نے فرمایا: تیرے قبضے میں جو چوپائے ہیں اگر وہ تجھے مجبور کر دیں تو ان کے ذبح کرنے کا طریقہ شکار کی مثل ہے۔ اور اونٹ کنویں میں گر جائے تو اس کو جس طرح تو کر سکے ذبح کر دے۔ یہ قول ہے علی، ابن عباس اور عائشہ رضی اللہ عنہم کا ہے۔‘‘ (البخاری ترجمہ الباب)","",{"k":"بخاری تعلیقاً، مع فتح الباری: 9/638۔","e":"مرفوع تو ثابت نہیں یہ اقوال صحابہ رضی اللہ عنہم ہیں مجبوری کی صورت میں جانور ضائع کرنے کی بجائے اس طرح ذبح کرنا جائز ہے۔ (فتح الباری مذکور)"}],[3891,"سیدنا ابن عباس اور سیدنا ابو ہریرہ رضی اللہ عنہما کا بیان ہے کہ نبی کریم صلی اللہ علیہ وسلم نے شیطان کے شریطہ سے منع فرمایا ہے۔ ابن عیسیٰ اپنی حدیث میں اس کی تفسیر اس طرح بیان کرتا ہے: ’’وہ یہ ہے کہ حلق سے جلد کاٹ کر رگیں چھوڑ دی جائیں اور کاٹی نہ جائیں اور پھر حیوان کو رہنے دیا جائے یہاں تک کہ وہ مر جائے۔‘‘ (ابوداؤد)","",{"k":"ابو داؤد (2826)، ضعیف، البانی: 605، احمد (261)۔","e":"یہ حدیث اگرچہ ضعیف ہے، مگر جانور کو ذبح کے وقت تکلیف نہ پہنچاؤ جو صحیح احادیث میں آتا ہے یہ طریقہ ان کی نگاہ میں نہایت ہی ظالمانہ ہے۔"}],[3892,"سیدنا ابو سعید خدری رضی اللہ عنہ کا بیان ہے کہ رسول اکرم صلی اللہ علیہ وسلم نے فرمایا: پیٹ کے بچے کے لیے ماں کا ذبح کرنا ہی اس کا ذبح کرنا ہے۔‘‘ (ترمذی)","",{"k":"ترمذی (1476)، صحیح، البانی: 1193، ابوداؤد (2827)، ابن ماجہ (3199)، احمد (11103)۔"}],[3893,"سیدنا ابو سعید خدری رضی اللہ عنہ کا بیان ہے کہ میں نے رسول اکرم صلی اللہ علیہ وسلم سے پیٹ کے بچے کے متعلق سوال کیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: کھانا چاہو تو کھا لو۔ مسدد کی روایت میں ہے کہ سیدنا ابو سعید الخدری رضی اللہ عنہ نے کہا: ہم نے عرض کی: یا رسول اللہ! ہم اونٹنی گائے اور بکری ذبح کرتے ہیں اور اس کے پیٹ میں بچہ ہوتا ہے کیا ہم اس کو پھینک دیں یا اس کو کھائیں؟ فرمایا: اگر تم چاہو تو کھا لو، اس کا ذبح وہ ہے جو اس کی ماں کا ذبح ہے۔ (ابوداؤد)","",{"k":"ابوداؤد (2827)، صحیح، البانی: 2451، ترمذی (1476)، ابن ماجہ (3199)۔"}],[3894,"سیدنا ابن عمر رضی اللہ عنہما کہا کرتے تھے کہ جب تم اونٹنی کو ذبح کرو تو اس کے پیٹ کے بچے کا وہ ذبح ہے جو اس کی ماں کا ذبح ہے جب کہ اس کی تخلیق مکمل ہو چکی ہو اور اس پر بال آگئے ہوں۔ وہ جب ماں کے پیٹ سے خارج ہو تو اس کو ذبح کر دو تاکہ اس کے پیٹ سے خون نکل جائے۔‘‘ (مالک)","",{"k":"مؤطا (1061)۔","e":"اس سے ثابت ہوا جب جانور ذبح کیا جائے اس کے پیٹ سے بچہ نکلے تو وہ اپنی ماں کے تابع ہے جس طرح اس کی ماں ذبح ہوئی ہے یہ خود بخود ہی ذبح ہوا ہے، یہ حلال ہے۔ امام ابوحنیفہ رحمہ اللہ سے منقول ہے کہ اس بچے کو نئے سرے سے ذبح کیا جائے گا۔ یہ احادیث اس موقف کی واضح تردید کرتی ہیں۔ (تفہیم الاسلام: ۲/۷۴۳)"}],[3895,"عبایہ بن رفاعہ اپنے دادا رافع بن خدیج سے روایت کرتا ہے، انہوں نے کہا: ہم لوگ تہامہ سے لوٹ کر مقام ذوالحلیفہ میں آنحضرت صلی اللہ علیہ وسلم کے ساتھ تھے اور لوگ بھوکے تھے۔ ان کو اونٹ اور بکریاں ہاتھ آئیں۔ رسول اللہ صلی اللہ علیہ وسلم قوم کے آخری حصے میں چلے آ رہے تھے۔ تو لوگوں نے جلدی میں ذبح کر کے ہنڈیاں چولہوں پر چڑھا دیں۔‘‘ رسول اللہ صلی اللہ علیہ وسلم نے ہنڈیاں خالی کرنے کا حکم دیا پھر گوشت تقسیم کیا اور دس بکریاں ایک اونٹ کے برابر قرار دیں۔ ان میں ایک اونٹ بگڑ کر بھاگ گیا، لوگوں نے پیچھا کیا اور عاجز آگئے۔ فوج میں گھوڑے تھوڑے تھے۔ پس ایک آدمی نے اونٹ کو تیر مارا تو اونٹ کو اللہ نے روک دیا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ان چوپائیوں میں وحشت اور بگاڑ ہوتا ہے جیسا وحشی جانوروں میں ہوتا ہے، پس جو حیوان تم پر غالب آجائے اس کے ساتھ اسی طرح کیا کرو۔ ہم نے عرض کیا: یا رسول اللہ! کل کو ہم دشمن کے مقابل ہوں گے اور ہمارے پاس چھری کوئی نہیں ہے، تو کیا ہم بانس کی لکڑی سے ذبح کر سکتے ہیں؟ فرمایا: جو چیز خون بہا دے اور بوقت ذبح بسم اللہ پڑھی جائے تو اس کو کھاؤ۔ ذبح کرنے کے لیے دانت یا ناخن استعمال نہ کیا جائے۔ میں ابھی اس کی وضاحت کرتا ہوں۔ دانت تو ہڈی میں شمار ہوتا ہے اور ناخن اہل حبشہ کی چھری ہے۔ (بخاری)","",{"k":"بخاری (5498)، مسلم (1968)، ترمذی (1492)، نسائی (4410)، ابوداؤد (2821)، ابن ماجہ (3183)، احمد (16832)، دارمی (1977)۔","e":"تلوار، چھری، تیز پتھر لکڑی، شیشہ، سرکنڈا بانس، ٹھکری، تانبے یا لوہے کی ساختہ چیزیں جو رگیں کاٹیں اور خون بہائیں تو اس سے ذبح کرنا جائز ہے۔ دانت اور ہڈی اور ناخن سے جانور ذبح کرنا منع ہے۔ ہڈی چونکہ جنوں کی خوراک ہے اور ناخن سے ذبح کرنے میں کفار کی مشابہت ہے اور یہ گلا گھونٹ کر مرنے کے حکم میں آتا ہے، اس لیے اس سے ذبح کرنے سے منع کیا گیا ہے۔ گردن میں چار رگیں ہیں (۱) گلے والی رگ۔ (۲) سانس والی رگ۔ (۳) کھانے پینے والی رگ۔ (۴) گردن کی دونوں جانب ایک ایک رگ ہوتی ہے۔ جانور ایسے انداز پر ذبح کریں کہ یہ چاروں رگیں کٹ جائیں۔ اس سے صحت بھی بہتر رہتی ہے کیونکہ تمام خون نکل جاتا ہے، دوسرا جانور کو راحت ہوتی ہے۔ ۲۔ اگر جانور دور ہو، پکڑا نہ جائے تو اسے گولی سے یا کسی بھی تیز دھار آلہ سے زخمی کیا جائے اور بعد میں ذبح کر لیا جائے تو جائز ہے۔ مسئلہ: بجلی کا جھٹکا دے کر جو جانور مر جائے وہ مردار ہے، اس کا گوشت حلال نہیں۔ (تفہیم الاسلام: ۲/۷۴۰) ۳۔ جب کوئی جانور بدک کر بھاگ جائے اور وحشی کی حیثیت میں ہو جائے تو مجبوراً اس کا پورا وجود ذبح کا مقام بن جاتا ہے۔ عام حالات میں صرف وہی ذبیحہ درست ہوگا جو گلے کی رگوں کو کاٹ کر کیا جائے یا پھر لبہ میں برچھا مار کر ذبح کیا جائے جیسا کہ اونٹ ذبح کیا جاتا ہے۔ (فتح الباری: ۹/۶۲۹)"}],[3896,"سیدنا عدی بن حاتم رضی اللہ عنہ فرماتے ہیں میں نے عرض کیا یا رسول اللہ! ہم میں سے کسی کو شکار ہاتھ آتا ہے اور اس کے پاس چھری نہیں ہوتی تو وہ پتھر سے یا لاٹھی کی پھاڑ والی طرف سے ذبح کر سکتا ہے؟ فرمایا: تو خون جاری کر جس چیز کے ساتھ کر سکے اور اللہ تعالیٰ کا نام ذکر کر۔‘‘ (ابوداؤد)","",{"k":"ابوداؤد (2824)، صحیح، البانی: 2450، بخاری (3297)، مسلم (1929)، ترمذی (1471)، نسائی (4263)، ابن ماجہ (3215)، احمد (18901)، دارمی (2002)۔"}],[3897,"’’سیدنا کعب بن مالک رضی اللہ عنہ کا بیان ہے کہ اس کی ایک باندی مقام سلع میں بکریاں چراتی تھی، اس نے بکری مرتے دیکھی تو اس نے پتھر توڑ کر اس کو تیزی کے ساتھ ذبح کر دیا۔ سیدنا کعب رضی اللہ عنہ نے ان کو کہا: تم اس کو مت کھانا یہاں تک کہ میں نبی صلی اللہ علیہ وسلم سے پوچھ یا کوئی شخص بھیجوں جو آپ سے پوچھ لے۔ پھر انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے سوال کیا: آپ صلی اللہ علیہ وسلم نے اس کو کھانے کا حکم دیا۔‘‘ (البخاری)","",{"k":"بخاری (2304)، ابن ماجہ (3182)، احمد (26627)، مؤطا (1057)۔"}],[3898,"’’عطاء بن یسار رحمہ اللہ نے بنو حارثہ کے آدمی سے روایت کی ہے کہ وہ اپنی دودھ والی اونٹنی چرا رہا تھا تو اس کو مرتے دیکھا، اور اس کو ذبح کرنے کے لیے کچھ نہیں میسر آیا تو اس نے ایک میخ پکڑی اور اس کے گلے میں مار کر خون بہا دیا۔ پھر نبی کریم صلی اللہ علیہ وسلم کو خبر دی، پس آپ صلی اللہ علیہ وسلم نے اس کو کھانے کا حکم دیا۔‘‘ (ابوداؤد)","",{"k":"ابوداؤد (2823)، صحیح، البانی: 2449، مؤطا (1056)۔"}],[3899,"’’سیدنا زید بن ثابت رضی اللہ عنہ نے بیان کیا کہ بھیڑئیے نے بکری میں دانت اتار دیا تو لوگوں نے اس کو تیز پتھر کے ساتھ ذبح کیا، پس رسول اللہ صلی اللہ علیہ وسلم نے اس کے کھانے کی اجازت دی۔‘‘ (النسائی)","",{"k":"نسائی (4407)، صحیح البانی: 4098، ابن ماجہ (3176)، احمد (21087)۔","e":"۱۔ ان احادیث سے ثابت ہوا کہ عورت کا ذبیحہ کھانا جائز ہے، وہ عورت خواہ آزاد ہو، یا لونڈی ہو، چھوٹی ہو یا بڑی ہو، مسلمان ہو یا کتابیہ ہو، پاک ہو یا حیض والی ہو۔ ۲۔ یہ بھی ثابت ہوا کہ جانور چھری کے علاوہ بھی کسی اور چیز سے ذبح ہو سکتا ہے، بشرطیکہ وہ نوکدار ہو، خون بہا دے۔ ۳۔ یہ بھی ثابت ہوا کہ بیمار جانور جو مرض الموت میں مبتلا ہو اسے ذبح کر کے اس کا گوشت کھانا حلال ہے۔\n۴۔ یہ بھی ثابت ہوا اگر چرواہا دیکھے کہ بکری وغیرہ مر جائے گی تو مالک سے پوچھے بغیر اسے ذبح کر دے تو جائز ہے اور اس کا گوشت کھانا حلال ہے یہ خیانت نہیں۔ (تفہیم الاسلام: ۲/۷۳۹)"}],[3900,"’’سیدنا ابو الدرداء رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے مجثمہ حیوان کو کھانے سے منع کر دیا۔ یہ وہ ہے جس کو تیر کے نشانہ کے لیے باندھا جائے۔","",{"k":"ترمذی (1473)۔","e":"ایسے جانور کا گوشت حرام قرار دیا گیا ہے، کیونکہ یہ مردار شمار کیا گیا ہے، ویسے ذبح کرنے کے لیے جانور کے ہاتھ پاؤں باندھنے جائز ہیں، یہ ممانعت اس جانور کے لیے ہے جسے نشانہ بنانے کے لیے باندھا گیا ہو۔ شریعت اسلامیہ نے جانوروں پر ذبح کرتے وقت تک بھی شفقت کرنے کا حکم دیا ہے۔ وجہ یہ ہے کہ اس طرح جانور کو تکلیف ہوتی ہے اور اس کی جان بے کار جاتی ہے۔ اس کی مالیت ضائع ہوتی ہے اور یہ شرعی ذبح کرنے کے بھی خلاف ہے۔ (تفہیم الاسلام: ۲/۷۴۱)"}],[3901,"’’رزین نے یہ بات زائد بیان کی ہے کہ آپ صلی اللہ علیہ وسلم نے خلیصہ سے منع فرمایا۔ یہ وہ حیوان ہے جس کو بھیڑئیے نے پکڑا لیکن اس سے مایوس ہو جانے کے بعد وہ جانور بچ گیا ہو۔‘‘","",{"k":"رزین۔","e":"اگر یہ جانور زندگی والا ہے تو اسے ذبح کرنا اور کھانا جائز ہے، اگر مر چکا ہے تو پھر نہیں۔"}],[3902,"’’سیدہ عائشہ رضی اللہ عنہا سے مروی ہے کہ لوگوں نے عرض کیا: یا رسول اللہ صلی اللہ علیہ وسلم! لوگ ہمارے پاس گوشت لاتے ہیں اور ہمیں معلوم نہیں ہوتا کہ انہوں نے اللہ کا نام لے کر ذبح کیا ہے یا نہیں؟ فرمایا: تم اس پر اللہ کا نام لے کر کھا لو۔ سیدہ عائشہ رضی اللہ عنہا نے فرمایا: ’’گوشت لانے والے نئے نئے کفر سے نکلے تھے۔‘‘ (بخاری)","",{"k":"بخاری (5507)، نسائی (4436)، ابوداؤد (2829)، ابن ماجہ (3174)، مؤطا (1054)، دارمی (1976)۔","e":"۱۔ اس سے ثابت ہوا دیہاتی مسلمان یا نو مسلم کا اور یہود و نصاریٰ کا ذبح کیا ہوا جانور حلال ہے، اگر اہل کتاب نے غیر شرعی طریقہ سے ذبح کیا ہو تو پھر جائز نہیں۔\nاگر غیر شرعی طریقہ کا علم نہ ہو تو ان کا ذبح کیا ہوا اور مسلمانوں کے بازاروں میں فروخت ہونے والا گوشت جائز ہے۔ مجوسی، مشرک، ملحد و بے دین اگر چہ بسم اللہ پڑھ کر بھی جانور ذبح کریں تو ان کا ذبح کیا ہوا جانور حلال نہیں۔ اسلام بے جا تکلف اور غلو سے روکتا ہے، اہل کتاب اور مسلمانوں سے درآمد کردہ گوشت کھانا اس نے حلال قرار دیا ہے۔ ۲۔ یہ جو مشہور ہے کہ مومن کا ذبح کیا ہوا جانور درست ہے یہ بسم اللہ پڑھے یا نہ پڑھے۔ یہ روایت ضعیف ہے۔ (بیہقی: ۹/۲۴۰) اس حدیث سے ثابت ہوتا ہے بسم اللہ پڑھنا ضروری ہے۔ (تفہیم الاسلام: ۲/۷۳۷)"}],[3903,"’’سیدنا دحیہ رضی اللہ عنہ کا بیان ہے کہ نبی کریم صلی اللہ علیہ وسلم کو اونی کپڑے کا جبہ اور دو موزے تحفہ دیئے گئے تو آپ صلی اللہ علیہ وسلم نے دونوں کو پہنا، یہاں تک کہ وہ پھٹ گئے اور آپ صلی اللہ علیہ وسلم نے نہیں پوچھا کہ وہ دونوں پاک ہیں یا نہیں۔‘‘ (الکبیر سند مخفی)","",{"k":"طبرانی کبیر: 4200، فیه عیینة بن سعد عن الشعبي، وعنه يحيى ابن ضريس ولم اعرفه، وبقية رجاله ثقات، هيثمي: 8627۔"}],[3904,"’’سیدنا عبداللہ ابن عباس رضی اللہ عنہما سے عرب کے عیسائیوں کی ذبح کردہ چیز کے متعلق سوال کیا گیا تو انہوں نے کہا: کوئی حرج نہیں، پھر یہ آیت تلاوت کی (جو شخص ان سے دوستی کرے گا وہ ان میں سے ہوگا)۔‘‘ (مالک)","",{"k":"مؤطا (1058)۔","e":"قرآن پاک میں بھی آتا ہے: ﴿وَ طَعَامُ الَّذِينَ أُوتُوا الْكِتَبَ حِلٌّ لَّكُمْ﴾ (المائدۃ: ۵) ’’اور ان لوگوں کا کھانا جو کتاب دیئے گئے ہیں، تمہارے لیے حلال ہے۔‘‘ عیسائی بھی چونکہ اہل کتاب ہیں اس لیے ان کا کھانا حلال ہے۔ اور ان کے ذبح کیے ہوئے جانور کا گوشت کھانا بھی حلال ہے۔ مگر قرآن پاک کا اعلان ہے: ﴿وَمَن يَتَوَلَّهُمْ مِنْكُمْ فَإِنَّهُ مِنْهُمْ﴾ (المائدۃ: ۵۱) ’’اور جو ان سے دوستی رکھے گا وہ انہی میں سے ہوگا۔‘‘ یعنی جانور ذبح ہونے یا کھانا حلال ہونے تک معاملہ رہے تو درست ہے، اس سے آگے زیادہ دوستی نہ ہو، اگر کوئی ان دشمنان الٰہی سے دوستی کرے گا تو انہی میں سے ہوگا۔ اور انہیں با قاعدہ طور پر ذبح کے لیے مقرر نہ کریں وہ مسلمان ہی مقرر کریں۔ (شرح زرقانی: ۸۲/۳)"}],[3905,"’’سیدنا عبداللہ ابن عباس رضی اللہ عنہما کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے بدویوں کا ایک دوسرے کے مقابلہ میں ذبح کیے ہوئے جانوروں کا گوشت کھانے سے منع کر دیا۔‘‘ (ابوداؤد)","",{"k":"ابوداؤد (2820)، حسن، صحیح، البانی: 2446۔","e":"اگر دیہاتی مسلمان ہو، جانور ذبح کرے، اور شرعی طریقہ کے مطابق ذبح کرے تو یہ ذبیحہ درست ہے۔ اس حدیث میں جو دیہاتیوں کی چیر پھاڑ سے منع کیا گیا ہے، وہ یہ ہے کہ کسی خوشی کے موقع پر یا ویسے ہی سخاوت میں فخر و مباہات کے لیے اونٹ ذبح کرتے تھے۔ اور دل میں یہ خیال ہوتا تھا کہ لوگ کہیں فلاں نے زیادہ اونٹ ذبح کیے ہیں اور پھر گوشت کا لوٹ بازار لگا دیتے جو جتنا چاہے لے جائے۔ اور ایک صورت یہ بھی تھی کہ اپنے بتوں کے نام پر اونٹ ذبح کرتے اور گوشت لے جانے کا اعلان عام کرتے۔ پہلی صورت بھی شرک خفی کی ہے۔ دوسری قسم غیر اللہ کا نام پکارنے کی ہے اس لیے دونوں صورتوں میں یہ گوشت کھانا جائز نہیں۔ آپ صلی اللہ علیہ وسلم نے ایک اللہ کی عبادت کا حکم دیا ہے۔ سیدنا علی رضی اللہ عنہ کوفہ میں تشریف فرما تھے کہ دو آدمیوں نے اس نظریہ سے سو اونٹ ذبح کیے، لوگ گوشت کے حصول کے لیے ٹوٹ پڑے تو کسی نے سیدنا علی رضی اللہ عنہ کو بتایا، وہ رسول اکرم صلی اللہ علیہ وسلم والے سفید خچر پر سوار ہو کر نکلے اور منادی کر دی کہ ان کا گوشت نہ کھانا یہ غیر اللہ کے نام پر پکارے گئے ہیں۔ (عون المعبود: ۶۰/۳)"}],[3906,"’’ابومرہ مولیٰ عقیل نے سیدنا ابو ہریرہ رضی اللہ عنہ سے اس بکری کے متعلق سوال کیا جو ذبح کی گئی اور اس کا کوئی حصہ حرکت کرتا تھا۔ تو انہوں نے اسے کھانے کا فتویٰ دیا۔ پھر اس نے سیدنا زید بن ثابت رضی اللہ عنہ کو پوچھا تو انہوں نے کہا: مردہ حیوان کبھی حرکت نہیں کرتا اور انہوں نے کھانے سے منع کر دیا۔‘‘ (مالک)","",{"k":"مؤطا (1060)۔","e":"اس صورت میں یہ مذبوحہ جانور نہ کھانے کی رائے صرف سیدنا زید بن ثابت رضی اللہ عنہ کی ہے۔ دیگر صحابہ کرام رضی اللہ عنہم عموماً اور خصوصاً سیدنا ابو ہریرہ رضی اللہ عنہ اور سیدنا ابن عباس رضی اللہ عنہما نے اس کی اجازت دی ہے۔ (شرح زرقانی: ۸۳/۳)"}],[3907,"’’انس رضی اللہ عنہ نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جب ذبیحہ پر بسم اللہ پڑھو تو ساتھ اللہ اکبر بھی کہو۔‘‘ (الاوسط سند ضعیف)","",{"k":"طبرانی اوسط فیه، عثمان بن عبدالرحمن القرشي وهو ضعيف، هيثمي: 6015۔","e":"صحیح احادیث سے یہ ثابت ہے کہ ذبیحہ پر بسم اللہ اکبر پڑھا جائے۔ (گوندلوی)"}],[3908,"’’معاویہ بن قرہ اپنے والد سے روایت کرتے ہیں کہ انہوں نے کہا: ایک آدمی نے کہا: یا رسول اللہ! میں بکری ذبح کرتا ہوں اور اس پر رحم کرتا ہوں۔ یا کہا: میں بکری کو ذبح کرنے سے اس پر رحم کرتا ہوں تو آپ نے فرمایا: اگر تو بکری پر رحم کرے گا تو تیرے اوپر اللہ تعالیٰ رحم کرے گا۔‘‘ (احمد)","",{"k":"احمد (15165)، بزار، طبرانی کبیر، طبرانی صغیر ورجاله ثقات، هيثمي: 6029۔"}],[3909,"البزار، الکبیر اور الصغیر کی روایت میں ہے: ’’میں بکری ذبح کرتا ہوں اور اس پر رحم کرتا ہوں۔‘ شک کے بغیر یہ الفاظ بیان کیے ہیں۔","",{"k":"بزار: 1221، احمد، طبرانی کبیر، طبرانی صغیر، رجاله ثقات، هيثمي: 6039۔"}],[3910,"’’سیدنا ابو امامہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: جس نے رحم کیا خواہ چڑیا ذبح کرتے وقت تو قیامت کے دن اللہ تعالیٰ اس پر رحم فرمائے گا۔‘‘","",{"k":"طبرانی کبیر: 7915 ورجاله ثقات، هيثمي: 6031۔","e":"یہ منظر رقت قلب پر دلالت کرتا ہے، اور رقیق القلب آدمی اللہ کو اچھا لگتا ہے، اس لیے اس وصف کی بنا پر ارحم الراحمین اس پر رحم کرے گا۔"}],[3911,"’’سیدنا عبداللہ ابن عباس رضی اللہ عنہما نے بیان کیا کہ نبی کریم صلی اللہ علیہ وسلم ایک آدمی کے پاس سے گزرے، تو اس نے بکری کے پہلو پر قدم رکھا تھا، اور چھری تیز کر رہا تھا اور بکری اس کی طرف دیکھ رہی تھی۔ فرمایا: تو نے چھری پہلے تیز کیوں نہ کی؟ کیا تو ارادہ کرتا ہے کہ بکری کو دوبار مارے؟‘‘ (کبیر، اوسط)","",{"k":"طبرانی کبیر، طبرانی اوسط: 11956، ورجاله رجال الصحيح، هيثمي: 6033۔"}],[3912,"سیدنا عبداللہ ابن عمر رضی اللہ عنہ کو ایک عورت نے کہا: اے عبداللہ! ٹڈی کے بارے میں ہمیں فتویٰ دو۔ انہوں نے کہا: سب ہی پاکیزہ ہیں (لہذا ذبح کرنے کی کوئی ضرورت نہیں)۔‘‘ (الکبیر)","",{"k":"طبرانی کبیر ورجاله رجال الصحيح، هيثمي: 6076۔","e":"اس پر اتفاق ہے کہ ٹڈی اور مچھلی مردہ بھی ہوں تو ان کا گوشت حلال ہے۔ (ابن ماجہ: ۳۲۲۰)"}],[3913,"سیدنا جابر رضی اللہ عنہ فرماتے ہیں کہ ہمارے ہاں رسول اللہ صلی اللہ علیہ وسلم تشریف لائے تو میں نے بکری ذبح کرنے کا ارادہ کیا۔ چنانچہ بکری نے اپنی آواز بلند کی اور آپ صلی اللہ علیہ وسلم نے سنی تو فرمایا: اے جابر! دودھ والی ذبح نہ کرو اور نہ نسل منقطع کرو۔ پس میں نے عرض کیا: یا رسول اللہ صلی اللہ علیہ وسلم! یہ بکری کا ایک سالہ بچہ ہے۔ میں نے اس کو کھجور کچے اور پکے کھلائے ہیں اور یہ موٹا تازہ ہو چکا ہے۔‘‘ (احمد سند مخفی ہے)","",{"k":"احمد (14843)، وفيه من لم اعرفه، هيثمي: 6084۔"}],[3914,"سیدنا عبداللہ ابن عباس رضی اللہ عنہ نے فرمایا: زمانہ جاہلیت میں لوگ بعض اشیاء کو کھاتے اور بعض کو ناپاک قرار دے کر ترک کرتے تھے۔ پس اللہ تعالیٰ نے اپنا رسول صلی اللہ علیہ وسلم مبعوث کیا اور اپنی کتاب نازل کی۔ حلال کو حلال قرار دیا اور جو حرام تھا اس کو حرام قرار دیا۔ پس جس کو حلال قرار دیا وہ حلال ہے اور جو چیز حرام کر دی وہ حرام ہے۔ اور جن اشیاء پر سکوت فرمایا وہ معاف ہیں۔ پھر یہ آیت تلاوت کی (کہو میں نہیں پاتا اس میں جو میری طرف وحی کی گئی ہے کوئی حرام کی گئی چیز جو چیز کھانے والے پر حرام کی گئی ہو ماسوا اس کے جو مردار ہو تا آخر آیت)۔‘‘ (ابوداؤد)","",{"k":"ابوداؤد (3800)، صحيح الاسناد، الباني: 3225۔","e":"آیت کی تکمیل یوں ہے:\n﴿ إِلَّا أَنْ يَكُونَ مَيْتَةً أَوْ دَمًا مَسْفُوحًا أَوْ لَحْمَ خِنْزِيرٍ فَإِنَّهُ رِجْسٌ أَوْ فِسْقًا أُهِلَّ لِغَيْرِ اللَّهِ بِهِ فَمَنِ اضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَإِنَّ رَبَّكَ غَفُورٌ رَحِيمٌ ﴾ [الانعام: ۱۴۵]\n’’کہہ دو، میں نہیں پاتا جو میری طرف وحی کیا گیا ہے حرام کیا ہوا کسی کھانے والے پر کہ وہ کھاتا ہے، مگر یہ کہ مردار ہو یا بہایا ہوا خون ہو یا خنزیر کا گوشت ہو، بے شک یہ حرام ہے یا فسق ہے جو غیر اللہ کے لیے پکارا گیا ہو پس جو مجبور کیا جائے سرکشی کرنے والا نہ ہو، نہ ہی حد سے بڑھنے والا ہو بیشک تیرا رب بخشنے والا مہربان ہے۔‘‘\nحدیث کا مطلب ہے کہ جاہلیت والے اپنی مرضی کے مطابق جن چیزوں کو چاہتے کھا لیتے تھے اور جس چیز کو چاہتے ناپسند کرتے اور گندہ قرار دیتے تھے۔ اب اللہ تعالیٰ نے نبی اکرم صلی اللہ علیہ وسلم کو مبعوث کیا، آپ پر وحی کے ذریعہ اللہ پاک نے اپنی مرضی سے کچھ چیزوں کو حلال قرار دیا اور کچھ کو حرام قرار دیا کہ یہ نہ کھائیں۔ اب یہ قانون چلے گا جس چیز کو اللہ حلال کہیں وہ حلال ہے، جسے اللہ حرام قرار دے اسے حرام کہیں، اب معیار وحی ہے، لوگ نہیں۔ اور جس پر حلال یا حرام کہنے سے خاموشی ہے، اس پر کوئی مواخذہ نہیں مرضی ہو تو کھائیں، مرضی ہو تو نہ کھائیں، کیونکہ اصل یہ ہے کہ کھانے کی چیز میں حلال ہیں الا کہ شریعت ان پر کوئی حکم لگائے۔ (عون المعبود: ۳/۴۱۷)"}],[3915,"قیصہ بن ہلب اپنے باپ سے روایت کرتے ہیں اس نے کہا: میں نے نبی کریم صلی اللہ علیہ وسلم سے سنا: جب کہ ایک مرد نے سوال کیا کہ بعض اشیاء کو کھانا میں گناہ سمجھتا ہوں؟ فرمایا: تیرے نفس میں یہ خلجان اور پریشانی آئندہ نہ رہے جس سے تو نصرانیت کے مشابہ ہو جائے گا۔‘‘ (ابوداؤد)","",{"k":"ابوداؤد (3784)، حسن، الباني: 3214، ترمذي (1565)، ابن ماجه (2830)، احمد (21458)۔","e":"اصل میں یہ مرغی کا گوشت تھا، انہوں نے کراہت کا اظہار کیا۔ یہ چونکہ صاف بھی ہے اور حلال بھی ہے۔ اس لیے انہیں کہا گیا یہ حلال اور جائز ہے تم تشدد کا شکار ہو چکے ہو، تم میں یہ عیسائیت پائی جاتی ہے۔ اسلام آسانی کا مذہب ہے، اس میں یہ تشدد جائز نہیں شک کی وجہ سے کھانے پینے میں تکلف درست نہیں۔ (عون المعبود: ۳/۴۱۲)"}],[3916,"سلیمان شیبانی کا بیان ہے کہ ابن ابی اوفی رضی اللہ عنہ نے فرمایا ہمیں خیبر کی راتوں میں فاقہ اور بھوک پیش آئی۔ جب خیبر کا دن تھا تو ہم نے پالتو گدھے ذبح کیے اور ہنڈیاں ابلنے لگیں۔ نبی کریم صلی اللہ علیہ وسلم کے منادی کرنے والے نے آواز دی کہ ہنڈیاں الٹا دو اور پالتو گدھے کا گوشت کوئی نہ کھائے۔ بعض لوگوں نے کہا: اس لیے منع کیا گیا ہے کہ اس میں سے خمس نہیں نکالا گیا تھا، اور بعض نے کہا: آپ صلی اللہ علیہ وسلم نے ہمیشہ کے لیے ممانعت کر دی ہے۔‘‘ (مسلم)","",{"k":"مسلم (1937)، بخاري (5526)، نسائي (4339)، ابن ماجه (3194)، احمد (18925)۔"}],[3917,"سیدنا انس رضی اللہ عنہ سے بھی اسی طرح کی روایت ہے، اس میں یہ بات بھی ہے کہ رسول اکرم صلی اللہ علیہ وسلم نے فرمایا: بے شک اللہ اور اس کا رسول تمہیں گدھے کا گوشت کھانے سے منع کرتا ہے کیونکہ گدھے ناپاک ہیں۔‘‘ (نسائی)","",{"k":"نسائي (4340)، صحيح، الباني: 4048، بخاري (5528)، مسلم (1940)، ابن ماجه (3196)، احمد (12260)، دارمي (1991)۔"}],[3918,"سیدنا ابن عباس رضی اللہ عنہ نے کہا: میں نہیں جانتا کہ رسول اللہ صلی اللہ علیہ وسلم نے گدھے کا گوشت کھانے کی ممانعت اس لیے کی کہ وہ لوگوں کی سواری کا کام دیتا ہے اور لوگوں کی سواریاں کم ہو جاتی تھیں اس لیے آپ صلی اللہ علیہ وسلم نے خیبر کے دن پالتو گدھوں کا گوشت حرام ہی قرار دے دیا۔‘‘ (مسلم)","",{"k":"مسلم (1939)، بخاري (4228)۔"}],[3919,"عمرو بن دینار کا بیان ہے کہ میں نے سیدنا جابر بن زید رضی اللہ عنہ کو کہا: لوگوں کا گمان ہے کہ نبی کریم صلی اللہ علیہ وسلم نے پالتو گدھوں کا گوشت کھانے کی ممانعت فرمائی ہے۔ اس نے کہا: یہ بات حکم بن عمرو غفاری بصرہ میں ہمارے پاس کہا کرتے تھے، مگر ایک بڑے عالم ابن عباس رضی اللہ عنہ اس سے انکار کرتے تھے اور یہ آیت تلاوت کی ’’کہو میں نہیں پاتا اپنی طرف کی گئی وحی میں حرام۔‘‘ (البخاری)","",{"k":"بخاري (5529)، ابوداؤد (3808)، احمد (17405)۔"}],[3920,"غالب بن ابجر کا بیان ہے کہ ہمیں قحط سالی پہنچی اور میرے پاس سوائے پالتو گدھوں کے گھر والوں کو کھلانے کے لیے کچھ نہیں تھا اور رسول اکرم صلی اللہ علیہ وسلم نے پالتو گدھوں کو حرام قرار دے دیا تھا۔ چنانچہ میں یہ صورت حال لے کر آنحضرت صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور عرض کیا: اے اللہ کے رسول صلی اللہ علیہ وسلم! ہم قحط سالی میں مبتلا ہیں۔ اور میرے پاس موٹے گدھوں کے سوا گھر والوں کو کھلانے کے لیے کچھ نہیں ہے اور آپ صلی اللہ علیہ وسلم نے گھریلو گدھوں کو حرام قرار دے دیا ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: اپنے اہل وعیال کو موٹا تازہ گدھا کھلا میں نے گدھے اس لیے حرام قرار دیئے ہیں کہ وہ بستی میں چکر لگاتے ہیں یعنی گندگی کھانا شروع ہو گئے ہیں۔‘‘ (ابوداؤد)","",{"k":"ابوداؤد (3809)، ضعيف الاسناد، مضطرب، الباني: 817۔"}],[3921,"سیدنا خالد بن ولید رضی اللہ عنہ کا بیان ہے کہ میں نے رسول اکرم صلی اللہ علیہ وسلم کے ساتھ غزوہ خیبر میں حصہ لیا۔ یہودیوں نے آپ کی خدمت میں حاضر ہوکر لوگوں کی شکایت کی کہ ہمارے مویشی پکڑ پکڑ کر کھا رہے ہیں۔ چنانچہ رسول اکرم صلی اللہ علیہ وسلم نے فرمایا: خبردار! ذمی کا مال حلال نہیں مگر اسکے حق کے ساتھ لیا جا سکتا ہے۔ تم پر پالتو گدھے، گھوڑے، خچر کچلوں والے درندے اور پنجوں میں پکڑنے والے پرندے حرام ہیں۔‘‘ (ابوداؤد)","",{"k":"ابوداؤد (3806)، ضعيف، الباني: 815، نسائي (4332)، ابن ماجه (3198)۔"}],[3922,"سیدنا جابر رضی اللہ عنہ بیان کرتے ہیں: ہم نے خیبر کے زمانے میں گھوڑے اور نیل گائے یعنی جنگلی گدھے کھائے ہیں اور رسول اللہ صلی اللہ علیہ وسلم نے پالتو گدھوں کے کھانے سے ہمیں منع کیا اور گھوڑے کا گوشت کھانے کی اجازت دی۔‘‘ (مسلم)","",{"k":"مسلم (1941)، بخاري (5534)، ترمذي (1793)، نسائي (4343)، ابوداؤد (3808)، ابن ماجه (3197)، احمد (14715)، دارمي (1993)۔","e":"۱۔ ان احادیث میں بیان ہوا ہے کہ ہر درندہ، پھلی والا جانور حرام ہے۔ مثلاً شیر، چیتا، بھیڑ یا وغیرہ اور جو بھی چیر پھاڑ کرنے والا ہو، اور طبعاً درندگی کرتا ہے۔ وہ حرام ہے، اگر کچلی نہ ہو یا درندگی طبعاً نہ ہو۔ تو پھر وہ جانور حرام نہیں۔ جیسا کہ بجو، اور لومڑی ہے، یہ حرام نہیں کیونکہ یہ حملہ آور نہیں ہوتے۔ اور جو پرندہ نیچے سے شکار کرتا ہو اور پنجے سے تعاون لیتا ہو یہ بھی حرام ہے، جیسا کہ باز وغیرہ۔ ۲۔ ان کچلی والے جانوروں اور پنجہ سے شکار کرنے والے پرندوں کو حرام قرار دینے میں عین فطرت کو مد نظر رکھا گیا ہے۔ ان جانوروں اور پرندوں کے پٹھے بہت سخت ہوتے ہیں اور ان کی بو گندی ہوتی ہے۔ ان کا گوشت انسانی معدہ کے لیے نقصان دہ ہے۔ یہ اپنے شکار میں اعصاب کی قوت استعمال کرتے ہیں اس طرح ان میں تناؤ پیدا ہوتا ہے۔ اگر انہیں کھایا جائے تو ہضم نہیں ہوتے۔ سبحان اللہ! دین اسلام کس قدر حکمت سے لبریز ہے۔ ۳۔ ان احادیث سے بالکل واضح ہے کہ پالتو اور گھریلو گدھوں کا گوشت کھانا حرام ہے اور گھوڑوں کا گوشت کھانا حلال ہے۔ اور جس طرح گدھے کا گوشت حرام ہے گدھی کا دودھ بھی حرام ہے۔ حرام ہونے کی وجہ نجس ہونا بھی ہو سکتی ہے اور ان پر سواری کی وجہ بھی ہو سکتی ہے۔ (تفہیم الاسلام: ۲/۷۲۲)"}],[3923,"سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے بلی کا گوشت اور اس کی قیمت کھانے سے منع فرمایا ہے۔‘‘ (ابوداؤد)","",{"k":"ابوداؤد (3807)، ضعيف، الباني: 816، ترمذي (1280)، ابن ماجه (3250)۔","e":"یہ حدیث تو ضعیف ہے تاہم مسلم میں سیدنا جابر رضی اللہ عنہ سے روایت مروی ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے بلی کی قیمت سے منع کیا ہے۔ (۱۵۶۹) کتاب البیوع والنهي عن بيع السنور۔ ثابت ہوا بلی یا بلے کی تجارت حرام ہے۔ بعض لوگ کہتے ہیں کہ یہ ممانعت تنزیہی ہے، لیکن ان کا یہ موقف حدیث کے مخالف ہونے کی وجہ سے ٹھیک نہیں ہے۔ ہاں قیمت یا خرید و فروخت بلی یا بلے کی حرام ہے۔ مگر اس کا جھوٹا پلید نہیں ہوتا اسے گھر میں رکھ بھی سکتے ہیں۔ (تفہیم الاسلام: ۲/۳۹)"}],[3924,"سیدنا عبداللہ ابن عباس رضی اللہ عنہ نے بیان کیا کہ نبی کریم صلی اللہ علیہ وسلم نے مجثمہ کا گوشت کھانے سے منع کیا ہے، یہ وہ جانور ہے جس کو تیر مارنے کے لیے باندھا ہو۔ اور فضلات اور گندگی کھانے والے حیوان کا گوشت کھانے اور اس کا دودھ پینے سے بھی ممانعت فرمائی ہے۔‘ (احمد)","",{"k":"احمد (2666)، بخاري (5629)، ترمذي (1825)، نسائي (4448)، ابوداؤد (3719)، ابن ماجه (3421)، دارمي (2117)۔"}],[3925,"سیدنا عبداللہ ابن عمر رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے گندگی کھانے والے حیوان پر سواری کرنے سے منع فرمایا ہے۔‘‘ (ابوداؤد)","",{"k":"ابوداؤد (2557)، صحیح، البانی: 2230۔"}],[3926,"زہدم بیان کرتے ہیں کہ ہم سیدنا ابوموسیٰ رضی اللہ عنہ کے پاس بیٹھے تھے، ہمارے اور جرم قبیلہ کی اس شاخ کے درمیان بھائی چارہ تھا۔ سیدنا ابوموسیٰ رضی اللہ عنہ کے پاس مرغی لائی گئی تو سرخ رنگ کا ایک آدمی اس جگہ سے علیحدہ ہو گیا۔ ابوموسیٰ رضی اللہ عنہ نے کہا: تیرا کیا حال ہے؟ میں نے رسول اکرم صلی اللہ علیہ وسلم کو مرغی کھاتے دیکھا ہے۔ اس نے کہا: میں نے مرغ گندگی کھاتے دیکھے ہیں۔ اس لیے میں ان کو ناپاک تصور کرتا ہوں اور میں نے قسم کھائی ہے کہ میں اس کو نہیں کھاؤں گا۔ تو سیدنا ابوموسیٰ رضی اللہ عنہ نے فرمایا: قریب آ کر کھاؤ۔ میں تمہیں رسول اللہ صلی اللہ علیہ وسلم کی حدیث سناتا ہوں، پھر انہوں نے حدیث بیان کی۔۔۔۔۔ الخ‘‘ (الشیخان)","",{"k":"بخاری (5517)، مسلم (1649)، ترمذی (1827)، نسائی (4347)، ابن ماجہ (2107)، احمد (1925)، دارمی (2056)۔","e":"اس کی تکمیل یہ ہے کہ ہم اشعر قبیلہ کے چند لوگ نبی اکرم صلی اللہ علیہ وسلم کے پاس آئے، آپ صلی اللہ علیہ وسلم کے رخ مبارک سے غصہ جھلک رہا تھا، آپ صدقہ کے جانور تقسیم کر رہے تھے، ہم نے سواریوں کا مطالبہ کیا۔ آپ نے قسم اٹھا کر کہا، میں تمہیں سواریاں نہیں دوں گا میرے پاس سواریاں ختم ہو چکی ہیں۔ اس کے بعد رسول اکرم صلی اللہ علیہ وسلم کے پاس اونٹ آئے، تو پوچھا، وہ اشعر قبیلہ والے کدھر ہیں، بلا کر آپ نے ہمیں سفید کوہانوں والے پانچ اونٹ دیئے۔ میں نے ساتھیوں سے کہا، شاید رسول اکرم صلی اللہ علیہ وسلم بھول گئے ہیں کہ میں نے قسم کھائی تھی کہ سواریاں نہ دوں گا۔ ہم واپس آ کر آپ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور آپ سے قسم کے بارے میں گزارش کی تو آپ صلی اللہ علیہ وسلم نے فرمایا: میں نے تم کو سواریاں نہیں دیں، اللہ نے دی ہیں، میں جب قسم اٹھاتا ہوں تو بہتر کام کرتا ہوں اور قسم کا کفارہ دے دیتا ہوں۔ ثابت ہوا مرغی اگرچہ گندگی کھاتی ہے، مگر یہ جلالہ گندگی خور جانور میں شامل نہیں اس کا گوشت حلال ہے، نبی اکرم صلی اللہ علیہ وسلم نے کھایا ہے۔ (فتح: ۹/۶۴۵)"}],[3927,"سیدنا عبدالرحمن بن شبل رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے گوہ کا گوشت کھانے سے منع فرمایا ہے۔‘‘ (ابوداؤد)","",{"k":"ابوداؤد (3796)، حسن، البانی: 3224۔"}],[3928,"سیدنا عبداللہ ابن عباس رضی اللہ عنہ سے روایت ہے کہ سیدنا خالد بن ولید رضی اللہ عنہ نے اسے بتایا کہ وہ میمونہ رضی اللہ عنہا کے گھر میں گئے وہ ان دونوں کی خالہ تھیں۔ تو ان کے پاس گوہ بھنی ہوئی تھی جس کو نجد سے ان کی بہن حفیدہ لے کر آئی تھی۔ اور میمونہ رضی اللہ عنہا نے وہ رسول اللہ صلی اللہ علیہ وسلم کو پیش کی۔ آپ صلی اللہ علیہ وسلم کے سامنے کوئی کھانا رکھا جاتا تو آپ صلی اللہ علیہ وسلم اس کے متعلق پوچھتے اور نام ذکر کرنے سے پہلے بہت کم ہاتھ بڑھاتے تھے۔ آپ صلی اللہ علیہ وسلم نے اس کی طرف ہاتھ بڑھایا تو ایک عورت نے کہا: رسول اللہ صلی اللہ علیہ وسلم کو بتا دو جو تم پیش کر رہی ہو۔ تو عورتوں نے کہا: یا رسول اللہ! یہ گوہ کا گوشت ہے۔ آپ صلی اللہ علیہ وسلم نے ہاتھ اٹھا لیا۔ خالد رضی اللہ عنہ نے کہا: یا رسول اللہ صلی اللہ علیہ وسلم کیا گوہ حرام ہے؟ فرمایا: نہیں، مگر یہ میری قوم کے علاقہ میں نہیں پائی جاتی اس لیے میں اس سے بچنے میں ہی عافیت سمجھتا ہوں۔ خالد رضی اللہ عنہ کا بیان ہے: میں نے وہ اپنی طرف کھینچ کر کھائی، آپ صلی اللہ علیہ وسلم دیکھ رہے تھے اور مجھے منع نہیں کیا۔‘‘ (احمد)","",{"k":"احمد (16374)، بخاری (5537)، مسلم (1948)، نسائی (5317)، ابوداؤد (3794)، ابن ماجہ (3241)، مؤطا (1805)، دارمی (2017)۔"}],[3929,"سیدنا عبداللہ ابن عباس رضی اللہ عنہ کی ایک روایت میں ہے کہ وہ سیدہ میمونہ رضی اللہ عنہا کے گھر میں تھے۔ پس نبی کریم صلی اللہ علیہ وسلم گھر میں آئے، آپ صلی اللہ علیہ وسلم کے ساتھ خالد رضی اللہ عنہ بھی تھے۔ افراد خانہ سلاخوں پر بھونی ہوئی دو عدد گوہ لے آئے، تو رسول اللہ صلی اللہ علیہ وسلم نے تھوک دیا۔ خالد رضی اللہ عنہ نے عرض کیا: یا رسول اللہ صلی اللہ علیہ وسلم! آپ اس کو ناپسند کرتے ہیں؟ فرمایا: ہاں۔‘‘ (ابوداؤد)","",{"k":"ابوداؤد (3730)، حسن، البانی: 3173، ترمذی (3455)، احمد (2565)۔"}],[3930,"اس طرح کی ایک اور روایت سیدنا عبداللہ بن عمر رضی اللہ عنہ سے مروی ہے جس میں ہے کہ آپ صلی اللہ علیہ وسلم نے فرمایا: تم کھاؤ یہ حلال ہے مگر یہ میری خوراک نہیں ہے۔‘‘","",{"k":"مسلم (1944)، بخاری (7267)، ترمذی (1790)، نسائی (4315)، ابن ماجہ (3242)، احمد (6429)، مؤطا (1806)، دارمی (2015)۔"}],[3931,"سیدنا ایک دوسری روایت میں ہے: ’’میں نہ تو اس کو کھاتا ہوں اور نہ اس کو حرام قرار دیتا ہوں۔‘‘ (مسلم)","",{"k":"مسلم (1943)، بخاری (7267)، ترمذی (1790)، نسائی (4315)، ابن ماجہ (3242)، احمد (6429)، مؤطا (1806)، دارمی (2015)۔"}],[3932,"سیدنا سمرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم سے گوہ کے متعلق سوال کیا گیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: نہ تو میں اس کو کھانے کا حکم دیتا ہوں اور نہ اس سے کسی کو منع کرتا ہوں مگر ہم آل محمد صلی اللہ علیہ وسلم اس کو کھانے والے نہیں ہیں۔‘‘ (اس کو الکبیر اور البزار نے روایت کیا اس میں محمد بن ابراہیم بن حبیب ہے)","",{"k":"طبرانی کبیر: 7072، بزار، وفيه محمد بن ابراهيم بن حبيب و لم اعرفه، هيثمي: 6064۔"}],[3933,"سیدنا ابوسعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ ایک اعرابی آیا اور نبی کریم صلی اللہ علیہ وسلم سے عرض کی کہ میں اس سر زمین میں رہتا ہوں جہاں گوہ بکثرت ہوتی ہے اور زیادہ تر خوراک میرے گھر کے لوگوں کی گوہ کا گوشت ہے؟ آپ صلی اللہ علیہ وسلم نے کوئی جواب نہ دیا۔ ہم نے کہا دوبارہ سوال کرو تو اس نے یہی بات دوبارہ پوچھی۔ پس آپ صلی اللہ علیہ وسلم نے جواب نہ دیا، تین بار اسی طرح ہوا۔ اور پھر تیسری بار رسول اللہ صلی اللہ علیہ وسلم نے اس کو آواز دی: اے اعرابی! اللہ تعالیٰ نے بنی اسرائیل کی ایک نسل پر لعنت کی یا غضب نازل کیا اور اس کو زمین پر رینگنے والے حیوانات بنا دیا تو وہ زمین پر رینگنے لگے۔ پس کیا معلوم یہ ان میں سے ہوں پس نہ تو میں ان کو کھاتا ہوں اور نہ ان سے منع کرتا ہوں۔‘‘ (مسلم)","",{"k":"مسلم (1951)، ابن ماجہ (3240)، احمد (11240)۔"}],[3934,"سیدنا عبداللہ ابن مسعود رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم سے بندر اور خنزیر کے متعلق پوچھا گیا کہ کیا وہ مسخ شدہ اقوام میں سے ہیں؟ تو فرمایا: اللہ تعالیٰ جس قوم کو مسخ کرتا یا عذاب دیتا ہے تو اس کی نسل جاری نہیں رکھتا اور تحقیق بندر اور خنزیر قوموں کے مسخ ہونے سے پہلے بھی موجود تھے۔‘‘ (مسلم)","",{"k":"مسلم (2663)، احمد (4427)۔"}],[3935,"سیدنا خزیمہ بن جزء رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے بجو کھانے کے متعلق سوال کیا: تو آپ صلی اللہ علیہ وسلم نے فرمایا: کیا کوئی بجو کو کھاتا ہے؟ میں نے بھیڑئیے کے بارے میں سوال کیا تو فرمایا: جس میں کوئی بھلائی ہو کیا وہ بھیڑیے کو بھی کھاتا ہے؟‘‘ (الترمذی)","",{"k":"ترمذی (1792)، ضعیف، البانی: 303، ابن ماجہ (3245)۔"}],[3936,"ابن ابی عمار فرماتے ہیں: میں نے جابر رضی اللہ عنہ سے پوچھا: کیا بجو شکار ہے؟ انہوں نے کہا: ہاں، میں نے پوچھا: کیا میں اس کو کھا لوں؟ انہوں نے کہا: ہاں، میں نے پھر پوچھا: کیا یہ بات نبی کریم صلی اللہ علیہ وسلم نے کہی ہے۔ انہوں نے اثبات میں جواب دیا۔‘‘ (الترمذی)","",{"k":"ترمذی (851)، صحیح، البانی: 676، نسائی (4323)، ابوداؤد (3801)، ابن ماجہ (3236)، احمد (14040)، دارمی (1942)۔"}],[3937,"میں سیدنا عبداللہ ابن عمر رضی اللہ عنہ کے پاس تھا، ان سے جنگلی چوہے کے بارے میں پوچھا گیا تو انہوں نے یہ آیت تلاوت کی (کہو میں نہیں پاتا اس میں جو میری طرف وحی کی گئی ہے کوئی حرام چیز الی آخر الآیہ) تو اس کے پاس ایک شیخ موجود تھے۔ انہوں نے کہا: میں نے سیدنا ابوہریرہ رضی اللہ عنہ کو بیان کرتے ہوئے سنا، نبی کریم صلی اللہ علیہ وسلم کے پاس اس چوہے کا ذکر گیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: وہ ناپاک اور خبائث میں سے ہے۔ تو سیدنا عبداللہ ابن عمر رضی اللہ عنہ نے فرمایا: اگر یہ ارشاد رسول اللہ صلی اللہ علیہ وسلم کا ہے تو پھر مسئلہ وہ ہے جو آپ صلی اللہ علیہ وسلم نے فرمایا ہے۔‘‘ (ابوداؤد)","",{"k":"ابوداؤد (3799)، ضعیف الاسناد، البانی: 814، احمد (8731)۔"}],[3938,"سیدنا خالد بن حویرث رضی اللہ عنہ فرماتے ہیں: ایک آدمی سیدنا عبداللہ بن عمرو رضی اللہ عنہ کے پاس خرگوش لے کر حاضر ہوا اور عرض کیا: اس کے متعلق تم کیا کہتے ہو؟ انہوں نے کہا: میں رسول اللہ صلی اللہ علیہ وسلم کے پاس بیٹھا تھا کہ یہ آپ صلی اللہ علیہ وسلم کے پاس لایا گیا، آپ صلی اللہ علیہ وسلم نے نہ تو اس کو کھایا اور نہ اس کے کھانے سے منع کیا۔ آپ صلی اللہ علیہ وسلم نے گمان کیا کہ اس کو حیض آتا ہے۔‘‘ (ابوداؤد)","",{"k":"ابوداؤد (3992)، ضعیف الاسناد، البانی: 811۔"}],[3939,"’’ہشام بن زید کا بیان ہے کہ سیدنا انس رضی اللہ عنہ نے کہا: مر الظہران میں ہمارے سامنے خرگوش نکلا تو لوگ دوڑے اور میں نے پہنچ کر پکڑا اور لے کر ابوطلحہ کے پاس آیا، انہوں نے پتھر سے ذبح کیا، اس کی ران یا سرین میرے ہاتھ میں دے کر مجھے رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں روانہ کیا۔ پس آپ صلی اللہ علیہ وسلم نے کھایا۔ راوی نے کہا: میں نے سیدنا انس رضی اللہ عنہ سے پوچھا: آپ نے کھا لیا؟ انہوں نے جواب دیا آپ نے قبول فرما لیا تھا۔‘‘ (ترمذی)","",{"k":"ترمذی (1789)، صحیح، البانی: 1461، بخاری (2572)، مسلم (1953)، نسائی (4312)، ابوداؤد (3791)، ابن ماجه (3243)، احمد (13692)، دارمی (2013)۔","e":"یہ واقعہ مر الظہران پر ہوا تھا، مکہ سے مدینہ کی جانب جائیں تو پانچ میل کے فاصلہ پر بستی ہے۔ یہاں یہ خرگوش تھا صحابہ کرام رضی اللہ عنہم نے آوازیں بلند کیں پتہ چل جائے کہ یہ خرگوش ہے۔ تب سیدنا انس رضی اللہ عنہ نے اسے پکڑا اور سیدنا ابوطلحہ رضی اللہ عنہ کے پاس لائے، انہوں نے اس کا گوشت آپ کی خدمت میں بھیجا۔ اس سے ثابت ہوا کہ خرگوش کا گوشت حلال ہے، نبی اکرم صلی اللہ علیہ وسلم نے اسے قبول کیا ہے۔ یہ بھی ثابت ہوا کہ شکار کو بے چین کرنا جائز ہے اور شکاری جو شکار کرے وہ اسی کی ملکیت ہے، اسے بھگانے والے اس میں حصہ دار نہ ہوں گے اور ہدیہ قبول کرنا چاہیے خواہ معمولی چیز ہی ہو۔ ۲۔ یہ جو خرگوش کے گوشت سے ممانعت والی حدیث ہے یہ حجت کے قابل نہیں یہ اس کے گوشت کھانے کی ممانعت پر دلیل نہیں بن سکتی۔ صحیح حدیث میں اس کے حلال ہونے کی دلیل آچکی ہے۔ (تفہیم الاسلام: ۲/۷۲۴)"}],[3940,"’’سیدنا سفینہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ سرخاب کا گوشت کھایا ہے۔‘‘ (ابوداؤد)","",{"k":"ابوداؤد (3797)، ضعیف، البانی: 812، ترمذی (1828)۔","e":"حُبَارَىٰ، یہ مذکر مؤنث دونوں پر بولا جاتا ہے، اس کا واحد اور جمع بھی یہی ہے، یہ ایک پرندہ ہے اس کی اڑان بہت تیز ہے۔ اور لمبے لمبے چکر لگاتا ہے، یہ خاکستری رنگ کا لمبی گردن والا پرندہ ہے، اس کا گوشت بطخ اور مرغی کے گوشت سے ملتا جلتا ہے۔ یہ حدیث ضعیف ہے، اس سے تو اس کے گوشت کے حلال ہونے کی دلیل نہیں مل سکی، تاہم بظاہر اس میں حرام والی علامت نہیں یہ حلال ہی ہے۔ (عون المعبود: ۳/۴۱۶)"}],[3941,"’’سیدنا عبداللہ ابن عمر رضی اللہ عنہ کا بیان ہے کہ رسول اکرم صلی اللہ علیہ وسلم نے فرمایا: ہمارے لیے دو مردہ اشیاء اور دو خون حلال کر دیئے گئے ہیں۔ دو مردہ اشیاء تو مچھلی اور ٹڈی ہیں اور دو خون جگر اور تلی ہیں۔‘‘ (ابن ماجہ سند ضعیف)","",{"k":"ابن ماجه (3314)، صحیح، البانی: 2679، احمد (5690)۔"}],[3942,"’’سیدنا سلمان رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم سے ٹڈی کے متعلق سوال کیا گیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: اللہ کی بڑی فوجوں میں سے ایسے جاندار بھی ہیں کہ نہ تو میں اس کو کھاتا ہوں اور نہ حرام قرار دیتا ہوں۔‘‘ (ابوداؤد)","",{"k":"ابوداؤد (3813)، ضعیف، البانی: 819، ابن ماجه (3219)۔"}],[3943,"’’سیدنا عبداللہ ابن ابی اوفی رضی اللہ عنہ نے بیان کیا کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ چھے یا سات غزوات میں شامل تھے اور ہم آپ صلی اللہ علیہ وسلم کے ساتھ ٹڈی کھاتے تھے۔‘‘ (بخاری)","",{"k":"بخاری (5495)، مسلم (1952)، ترمذی (1822)، نسائی (4357)، ابوداؤد (3812)، احمد (18908)، دارمی (2010)۔"}],[3944,"’’سیدنا جابر رضی اللہ عنہ کا بیان ہے کہ نبی کریم صلی اللہ علیہ وسلم نے ٹڈیوں پر بددعا کی: یا اللہ! ٹڈی کو مار دے، اس کی بڑی ٹڈیوں کو بھی مار دے اور چھوٹیوں کو بھی ہلاک کر، اور ان کی جڑ کاٹ دے اور ان کے منہ ہماری معیشت اور رزق سے موڑ لے، تحقیق تو ہی دعا قبول کرنے والا ہے۔ ایک آدمی نے عرض کیا: یا رسول اللہ! آپ ٹڈیوں کے لیے بددعا کیوں کرتے ہیں؟ جب کہ وہ اللہ کی فوجوں میں سے ایک فوج ہے۔ فرمایا: یہ سمندر میں مچھلی کا بکھیر ہے۔‘‘ (رزین)","",{"k":"رزین۔","e":"ٹڈی کے حلال ہونے پر مسلمانوں کا اجماع ہے، سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ ازواج مطہرات رضی اللہ عنہن پیٹیوں میں رکھ کر آپس میں ہدیہ کے طور پر دیتی تھیں۔ خواہ یہ زندہ ہو خواہ یہ مردہ ہو، مسلمان پکڑے یا غیر مسلم پکڑے اسے کھانا بالکل جائز ہے۔ یہاں جو حدیث میں آیا ہے کہ آپ صلی اللہ علیہ وسلم نے فرمایا: میں اسے نہ تو کھاتا ہوں اور نہ حرام قرار دیتا ہوں۔۔۔۔۔۔ الخ یا جو بددعا کی ذکر ہے۔ اس کا حل یہ ہے کہ یہ آپ نے طبعی کراہت کا اظہار کیا ہے اسے حرام قرار نہیں دیا۔ دوسری بات یہ ہے کہ یہ حدیث ضعیف ہے اس کے حلال قرار دینے والی احادیث کے ہم پلہ نہیں۔ ٹڈی خبیث چیزوں میں شامل نہیں یہ حلال ہے۔ (تفہیم الاسلام: ۲/۷۲۴)"}],[3945,"’’ملقام بن تلب اپنے باپ سے روایت کرتے ہیں انہوں نے کہا میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ رہا ہوں اور میں نے آپ صلی اللہ علیہ وسلم سے حشرات الارض اور کیڑے مکوڑوں کی حرمت کے متعلق کچھ نہیں سنا۔‘‘ (ابوداؤد)","",{"k":"ابوداؤد (3798)، ضعیف الاسناد، البانی: 813۔"}],[3946,"’’سیدنا وابصہ بن معبد رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ان تمام درندوں میں سے لومڑ سب سے زیادہ شریر ہے۔‘‘ (الکبیر سند ضعیف)","",{"k":"طبرانی کبیر: 22/144، وفیه مبشر بن عبيد وهو ضعيف، هيثمي: 6081۔","e":"لومڑ بھی درندوں میں شامل ہے، جائز نہیں۔ (گوندلوی)"}],[3947,"’’سیدہ عائشہ رضی اللہ عنہا فرماتی ہیں کہ مجھے تعجب ہے ان لوگوں پر جو کوا کھاتے ہیں۔ حالانکہ رسول اللہ صلی اللہ علیہ وسلم نے اس کو مارنے کا حکم دیا ہے اور اس کا نام فاسق رکھا ہے اللہ کی قسم! وہ پاکیزہ اشیاء میں سے نہیں ہے۔‘‘ (بزار)","",{"k":"بزار: 1214، ورجاله ثقات، هيثمي: 6082۔","e":"یہ بھی حرام پرندوں میں سے ہے، یہ درست بات ہے۔"}],[3948,"’’سیدنا عبداللہ ابن عمر رضی اللہ عنہما کا بیان ہے کہ رسول اکرم صلی اللہ علیہ وسلم نے فرمایا: چار حیوانات ہیں جن کے مارنے سے احرام والے پر کوئی گناہ لازم نہیں ہوتا، کوا، چیل، بچھو، چوہا اور کاٹنے والا کتا۔‘‘ (مسلم)","",{"k":"مسلم (1199)، بخاری (1828)، نسائی (2890)، ابوداؤد (5252)، ابن ماجه (3535)، احمد (6193)، مؤطا (699)، دارمی (1817)۔"}],[3949,"’’ایک روایت میں ہے کوئی گناہ نہیں اس پر جس نے ان کو حرم میں یا حرم کے باہر قتل کیا۔‘‘ (ابوداؤد)","",{"k":"ابوداؤد (1846)، صحیح، البانی: 1629، بخاری (3315)، مسلم (1199)، نسائی (2835)، ابن ماجه (3088)، احمد (6193)، دارمی (1816)۔"}],[3950,"’’ایک روایت میں ہے سانپ، بچھو، چوہا یعنی فویسقہ، کاٹنے والا کتا، حملہ کرنے والا درندہ یہ سب قتل کیے جائیں اور کوے کو کنکر مارا جائے اور بحالت احرام قتل نہ کیا جائے اور چیل کو بھی۔‘‘ (احمد)","",{"k":"احمد (10607)، ابوداؤد (1848)، ابن ماجه (3089)، ترمذی (838)۔"}],[3951,"’’سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: پانچ حیوانات میں ہر ایک فاسق ہے اور ان کو حرم اور حرم کے باہر ہر جگہ قتل کیا جائے گا: کاٹنے والا کتا، کوا، چیل، بچھوا اور چوہا۔‘‘ (نسائی)","",{"k":"نسائی (2887)، صحیح، البانی: 2704۔"}],[3952,"’’سیدنا عبداللہ ابن مسعود رضی اللہ عنہ بیان کرتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ (مقام منیٰ) کے ایک غار میں تھے۔ جب آپ صلی اللہ علیہ وسلم پر سورت المرسلات عرفاً نازل ہوئی، آپ صلی اللہ علیہ وسلم اس کی تلاوت کر رہے تھے اور ہم آپ کے منہ مبارک سے اخذ کر ہی رہے تھے کہ اتنے میں ہم پر سانپ گر پڑا۔ پس جلدی سے ہم اس کی طرف بڑھے تاکہ اس کو مار دیں اور وہ ہم سے پہلے ہی بھاگ گیا اور اپنے سوراخ میں داخل ہو گیا۔ تو آپ صلی اللہ علیہ وسلم نے فرمایا: وہ تمہارے شر سے اور تم اس کے شر سے بچائے گئے۔‘‘","",{"k":"بخاری (3317)، مسلم (2235)، نسائی (2884)، احمد (439)۔"}],[3953,"’’ابو عبیدہ اپنے والد عبداللہ بن مسعود رضی اللہ عنہ سے روایت کرتے ہیں، انہوں نے کہا: ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ عرفہ کی رات موجود تھے، اچانک سانپ محسوس ہوا تو آپ صلی اللہ علیہ وسلم نے فرمایا: اس کو مار دو! تو وہ ایک سوراخ میں داخل ہو گیا۔ ہم نے سوراخ میں لکڑی داخل کی اور سوراخ کا کچھ حصہ کھودا اور گھاس لیا اور اس میں آگ سلگائی۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اللہ تعالیٰ نے تمہارے شر سے اس کو اور اس کے شر سے تم کو بچا لیا۔‘‘ (النسائی)","",{"k":"نسائی (2884)، صحیح، البانی: 2701، بخاری (4934)، مسلم (2234)، احمد (4344)۔"}],[3954,"’’سیدنا عبداللہ ابن عمر رضی اللہ عنہ مرفوعاً روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا: سانپوں کو مار دیا کرو، اور خبیث چار چشمہ اور دم کٹا سانپ بالخصوص مار دیا کرو، یہ دونوں آنکھوں کی روشنی مٹاتے اور حاملہ کا حمل گراتے ہیں۔ سیدنا عبداللہ ابن عبداللہ رضی اللہ عنہ نے فرمایا: اتفاقاً میں ایک سانپ کے تعاقب میں تھا کہ ابو لبابہ رضی اللہ عنہ نے آواز دی کہ اس کو نہ مارو۔ میں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے سانپوں کو مارنے کا حکم دیا ہے۔ تو اس نے کہا: بعد میں آپ صلی اللہ علیہ وسلم نے گھروں میں رہنے والے سانپوں کو مارنا منع فرمایا ہے اور یہ سانپ آبادی میں رہنے والے ہیں۔‘‘ (البخاری)","",{"k":"بخاری (3299)، مسلم (2233)، نسائی (2889)، ابوداؤد (5252)، ابن ماجه (3535)، احمد (26593)، مؤطا (799)، دارمی (1816)۔"}],[3955,"سیدہ عائشہ رضی اللہ عنہا کی باندی سیدہ سائبہ رضی اللہ عنہا سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے ان سانپوں کو مارنے سے منع کیا ہے جو گھروں میں رہتے ہیں مگر چار چشمہ اور دم کٹا سانپ جہاں ملے مارنے کا حکم دیا ہے کیوں کہ یہ دونوں آنکھوں کی بینائی زائل کرتے ہیں اور عورتوں کے پیٹ میں جو کچھ ہے اس کو گرا دیتے ہیں۔‘‘ (مالک)","",{"k":"مؤطا (1827)، بخاری (3308)، مسلم (2232)، احمد (25407)۔"}],[3956,"ابو سائب کا بیان ہے: میں ابو سعید خدری رضی اللہ عنہ کے گھر گیا تو اس کو نماز پڑھتے پایا، میں بیٹھ کر ان کا انتظار کرنے لگا، یہاں تک کہ وہ نماز مکمل کر دے۔ گھر کے ایک طرف کھجور کی شاخوں میں مجھے حرکت محسوس ہوئی تو دیکھا کہ ایک سانپ تھا۔ میں مارنے کے لیے جلدی سے اٹھا تو ابو سعید خدری رضی اللہ عنہ نے بیٹھنے کا اشارہ کیا اور میں بیٹھا رہا۔ جب نماز مکمل کی تو گھر سے ایک مکان کی طرف اشارہ کیا اور کہا وہ مکان تجھے نظر آتا ہے؟ میں نے کہا: ہاں، اس نے کہا: اس مکان میں ہمارا ایک نوجوان تھا۔ اس کی نئی شادی ہوئی تھی کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ خندق کی جنگ کے موقع پر خندق کی طرف نکلے، تو یہ نوجوان دن کے نصف وقت میں رسول اللہ صلی اللہ علیہ وسلم سے اجازت لے کر اپنے اہل والوں کی طرف لوٹ جاتا تھا۔ ایک دن اس نے اجازت طلب کی تو آپ صلی اللہ علیہ وسلم نے اس کو فرمایا: اپنا اسلحہ لے جاؤ مجھے بنو قریظہ کا تیرے بارے میں خطرہ لگتا ہے۔ تو اس جوان نے اپنا اسلحہ لے لیا۔ پھر وہ گھر لوٹا تو اس کی بیوی دروازے کے درمیان کھڑی تھی، اس نے عورت کی طرف نیزہ سیدھا کیا تا کہ اس کو مارے، کیونکہ اس کو غیرت آئی تھی۔ عورت نے کہا: اپنا نیزہ روک دے اور گھر میں دیکھ کہ مجھے کس چیز نے باہر نکالا ہے۔ وہ اندر گیا تو دیکھا ایک بہت بڑا سانپ بستر پر جمع ہو کر بیٹھا ہے۔ تو اس نے نیزہ مار کر سانپ کو نیزے کے ساتھ پرو کر باہر لے جا کر اس کو مارنا شروع کر دیا۔ پس اس پر کپکپی ہوئی اور اضطراب پیدا ہوا اور یہ معلوم نہ ہو سکا کہ ان دو میں سے کون پہلے موت کی آغوش میں چلا گیا؟ سانپ پہلے مرا یا وہ جوان۔ ہم لوگ رسول اللہ صلی اللہ علیہ وسلم کے پاس دوڑ کر گئے، آپ صلی اللہ علیہ وسلم سے یہ قصہ بیان کیا اور ہم نے عرض کیا کہ آپ صلی اللہ علیہ وسلم اللہ سے دعا کریں کہ اس کو زندہ کر دے۔ پس آپ صلی اللہ علیہ وسلم نے فرمایا: تم اپنے رفیق کے لیے دعا مغفرت کرو۔ پھر فرمایا: مدینہ کے جنات اسلام لے آئے ہیں تو جب تم ان میں سے کسی کو دیکھو تو تین ایام تک اس کو خبر دار کرو۔ اور اس کے بعد اگر تمہیں یہاں نظر آئیں تو اس کو مار ڈالو کہ وہ شیطان ہے۔‘‘ (مسلم)","",{"k":"مسلم (2236)، ترمذی (1484)، ابوداؤد (5257)، احمد (10976)، مؤطا (1828)۔"}],[3957,"ایک روایت میں ہے کہ ان گھروں میں کچھ آباد رہنے والے ہیں۔ جب تم ان کو دیکھو تو تین دن ان پر تنگی کرتے رہو اگر چلا جائے تو بہتر ورنہ اس کو قتل کر دو۔ وہ شیطان ہے۔ پھر انہیں فرمایا: جا کر اپنے اس ساتھی کو دفن کر دو۔‘‘ (مسلم)","",{"k":"مسلم (2236)۔"}],[3958,"ابن ابی لیلیٰ اپنے باپ سے روایت کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم سے گھر کے سانپوں کے متعلق سوال کیا گیا: آپ صلی اللہ علیہ وسلم نے فرمایا: جب تم ان میں سے کسی کو اپنے گھروں میں دیکھو تو تم کہو: ہم تمہیں وہ عہد یاد دلاتے ہیں جو نوح علیہ السلام نے تم سے لیا ہے اور تمہیں وہ عہد یاد دلاتے ہیں جو سلیمان علیہ السلام نے تم سے لیا ہے نہ تو تم ہم کو ایذا پہنچاؤ اور نہ ہمارے سامنے آؤ۔ اس کے بعد بھی اگر وہ نظر آئیں تو ان کو مار دو۔‘‘ (ابوداؤد)","",{"k":"ابوداؤد (5260)، ضعیف، البانی: 1126، ترمذی (1485)۔"}],[3959,"سیدنا عبداللہ ابن مسعود رضی اللہ عنہ مرفوعاً بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: تمام سانپوں کو مار دیا کرو اور جو شخص ان کے انتقام سے خوف کھائے گا وہ مجھ سے نہیں ہے۔‘‘ (ابوداؤد)","",{"k":"ابوداؤد (5249)، صحیح، البانی: 4371، نسائی (3193)۔"}],[3960,"اور ایک روایت میں ہے کہ تمام بڑے سانپوں کو مارو مگر اس کو جو جان سفید رنگ کا ہو گویا وہ چاندی کی لاٹھی ہے۔ ابو داؤد رحمہ اللہ فرماتے ہیں: مجھے ایک آدمی نے بتایا کہ جن اپنی چال میں ٹیڑھا نہیں ہوتا اگر یہ بات صحیح ہے تو یہ چیز اس میں ان شاء اللہ نشانی ہوگی۔","",{"k":"ابوداؤد (5261)، صحیح موقوف، البانی: 4381۔"}],[3961,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جب سے سانپوں کے ساتھ ہماری جنگ ہوئی ہے ہم نے ان سے صلح نہیں کی، جس نے کسی قسم کا سانپ ڈر کر مارنا ترک کیا وہ ہم میں سے نہ ہوگا۔‘‘ (ابوداؤد)","",{"k":"ابوداؤد (5248)، حسن صحیح، البانی: 4370، احمد (10363)۔"}],[3962,"سیدنا عباس رضی اللہ عنہ نے عرض کیا: یا رسول اللہ صلی اللہ علیہ وسلم! ہم ارادہ کرتے ہیں کہ زم زم کنویں کی صفائی کرائیں اور اس میں یہ جنان یعنی چھوٹے سانپ ہیں؟ پس رسول اللہ صلی اللہ علیہ وسلم نے ان کو قتل کرنے کا حکم دیا۔‘‘ (ابوداؤد)","",{"k":"ابوداؤد (5251)، صحیح، البانی: 4373۔","e":"یہ وہ جانور ہیں جن کی طبیعت میں اذیت رسانی ہے۔ اس لیے انہیں حرم یا غیر حرم میں مارنے کا حکم ہے۔ ان کے علاوہ جو جانور یا زمینی کیڑے مکوڑے اذیت ناک ہوں انہیں مارنا بھی جائز ہے۔ مثلاً بھیڑیا، شیر، عقاب، چیچڑ وغیرہ کیونکہ اذیت رسانی میں یہ بھی حدیث میں مذکور جانوروں کی مانند ہیں بلکہ ان سے بھی زیادہ ہیں۔ احناف کی یہ رائے ہے کہ بس ان پانچ چیزوں کو مارنے پر ہی اکتفا کیا جائے اس کے علاوہ شامل نہیں۔ لیکن جمہور علمائے کرام کہتے ہیں کہ اس اذیت رسانی میں جو جانور بھی شامل ہوگا، وہ اس حکم میں آئے گا، اسے مارنا جائز ہے۔ یہی رائے وزنی ہے۔ جب ان جانوروں کے قتل کا حکم ہے تو پھر ان کا کھانا بھی حرام ہوا۔ (تفہیم الاسلام: ۱/۸۴۱) ۲۔ سانپوں کے مارنے کے متعلق جو احکامات ہیں، ان کا مطلب یہ ہے کہ انسان اور سانپ میں فطرتی طور پر جنگ آزمائی ہے۔ سانپ انسان کو مارنے کی کوشش کرتا ہے، انسان سانپ کو مارنے کی کوشش کرتا ہے۔ یہ مارنے کا حکم بعض کا خیال ہے صرف مدینہ کے گھروں میں رہنے والے سانپوں کے بارے میں۔ دوسرا قول ہے اور یہی صحیح ہے کہ یہ عام گھروں کے لیے ہے، انہیں پہلے تین دن تک کہنا چاہیے جو عہد حضرت نوح اور حضرت سلیمان علیہم السلام نے تم سے کیا ہے، ہم تمہیں وہی یاد کرواتے ہیں کہ آئندہ نظر نہ آنا اور جاہلیت میں یہ مشہور تھا اگر سانپ کی مادہ کو قتل کیا جائے تو اس کا نر خاوند آتا ہے اور ڈستا ہے، آپ صلی اللہ علیہ وسلم نے اس کی تردید فرمائی کہ جو اس جاہلیت کے خیال سے سانپ کو نہ مارے اسے یہ بھی خیال رکھنا ہوگا کہ وہ ہمارے طریقہ سے باہر چلا گیا ہے۔\nسانپوں کے جانے کی وارننگ کے بعد نظر آنے کی صورت میں مارنے کی پابندی گھر والے سانپوں کی ہے۔ جنگل وغیرہ یا باہر والوں کے ساتھ نہیں جیسا کہ حدیث میں مذکور ہے کہ نماز میں سانپ نظر آیا تو نبی اکرم صلی اللہ علیہ وسلم نے اسی وقت مار دینے کا حکم دیا تھا۔ (عون المعبود: ۴/۵۳۶)"}],[3963,"سیدنا سعد رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے چھپکلی مارنے کا حکم دیا اور اس کو چھوٹا بد کار قرار دیا۔‘‘ (مسلم)","",{"k":"مسلم (2238)، ابوداؤد (5262)، احمد (1526)۔"}],[3964,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا: جس نے اول ضرب کے ساتھ چھپکلی ماردی اس کے لیے اتنی اور اتنی نیکیاں لکھی جاتی ہیں۔ اور جس نے دوسری ضرب سے ماری تو اس کے لیے اتنی اتنی نیکیاں درج کی جاتی ہیں، جو اول مرتبہ سے کم ہیں۔ اور جس نے تیسری ضرب سے مار دی تو اس کے لیے اتنی اتنی نیکیاں درج کی جاتی ہیں جو دوسرے مرتبہ سے کم ہیں۔‘‘ (مسلم)","",{"k":"مسلم (2240)۔"}],[3965,"ایک روایت میں ہے: جس نے چھپکلی کو پہلی ضرب میں مار دیا اس کے لیے سو نیکی لکھی جاتی ہے اور دوسری ضرب سے مارنے پر اس سے کم اور تیسری ضرب پر اس سے کم نیکیاں لکھی جاتی ہیں۔‘‘ (مسلم)","",{"k":"مسلم (2240)، ترمذی (1482)، ابن ماجہ (3229)، احمد (8445)۔"}],[3966,"ام المومنین سیدہ عائشہ رضی اللہ عنہا کے پاس ایک عورت آئی اور ام المومنین کے ہاتھ میں لاٹھی دیکھ کر کہا: یہ کس لیے؟ تو انہوں نے کہا: ان چھپکلیوں کے لیے، اس لیے کہ نبی کریم صلی اللہ علیہ وسلم نے ہم سے بیان کیا ہے کہ ہر چیز ابراہیم علیہ السلام پر آگ بجھانے کی کوشش کرتی تھی مگر یہ حیوان۔ پس آپ صلی اللہ علیہ وسلم نے اس کے مارنے کا ہمیں حکم دیا ہے۔‘‘ (النسائی)","",{"k":"نسائی (2831)، صحیح، البانی: 2654۔"}],[3967,"سیدنا عبداللہ ابن عباس رضی اللہ عنہ مرفوع بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: تم چھپکلی کو مار دیا کرو خواہ کعبہ کے اندر بھی ہو۔‘‘ (الکبیر، سند ضعیف)","",{"k":"طبرانی کبیر، اور اوسط، وفیہ عمر بن قیس المکی وهو ضعیف۔","e":"وزغ، چھپکلی کو کہتے ہیں، یہ بھی ان میں شامل ہے جنہیں حرم اور غیر حرم میں مار دینے کا حکم ہے۔ نبی صلی اللہ علیہ وسلم نے اسے فویسق، یعنی سرکش قرار دیا ہے کیونکہ یہ ضرر رسانی میں تیز تر ہے۔ عام قاعدہ کلیہ یہ ہے کہ جتنی مشقت زیادہ ہو اجر زیادہ ہوتا ہے۔ مگر چھپکلی مارنے میں معاملہ الٹ ہے، پہلی دفعہ میں اجر زیادہ رکھا ہے۔ دوسری دفعہ میں اس سے کم، تیسری مرتبہ میں اس سے بھی کم، یہاں یہ اصول کار فرما ہے کہ مفاسد (خرابیاں) دور کی جائیں اور مصالح (فوائد) حاصل کیے جائیں، تو اس میں خرابی جتنی جلدی دور ہو جلدی چھپکلی مر جائے تو زیادہ اجر رکھا ہے، دیر لگے تو کم رکھا گیا ہے۔ اور کسی حدیث میں ثواب سو، کسی میں ستر گناہ بتایا گیا ہے۔ اس اختلاف کی وجہ یہ ہے کہ متعین حد نہیں ثواب کی بہتات اور کثرت بتانا مقصد ہے۔ دوسری وجہ یہ بھی ہو سکتی ہے کہ پہلے آپ صلی اللہ علیہ وسلم کو ایک تعداد بتائی گئی ہو اور پھر بعد میں تعداد اضافہ سے بتائی گئی۔ تیسری وجہ یہ بھی ہو سکتی ہے کہ یہ مارنے والے کے حالات کے اختلاف کی بنیاد پر ہے، وہ جتنا زیادہ اخلاص والا ہوگا اتنا اجر میں اضافہ ہوگا۔ (عون المعبود: ۴/۵۳۷)"}],[3968,"سیدنا عبداللہ بن عباس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ایک چٹائی پر تشریف فرما تھے۔ اور ایک چوہا چراغ کی بتی (فتیلہ) کھینچ کر لایا اور آپ صلی اللہ علیہ وسلم کے سامنے چٹائی پر رکھ دی اور چٹائی ایک درھم کی مقدار جل گئی۔ آپ صلی اللہ علیہ وسلم نے فرمایا: تم سوتے وقت اپنے چراغ بجھا دیا کرو، اس جیسے حیوانات کو شیطان بتاتا ہے تا کہ یہ تمہیں جلا ڈالیں۔‘‘ (ابوداؤد)","",{"k":"ابوداؤد (5247)، صحیح، البانی: 4369۔"}],[3969,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: بنو اسرائیل کی ایک قوم گم ہوگئی اور کوئی پتہ نہ چلا کہ کہاں گئی۔ اور میرا خیال ہے کہ وہ قوم چوہے کی شکل میں مسخ کر دی گئی ہے۔ جب چوہے کے سامنے اونٹوں کا دودھ رکھا جائے تو چوہا نہیں پیتا اور جب بکری کا دودھ رکھا جائے تو پیتا ہے۔‘‘ (بخاری)","",{"k":"بخاری (3305)، مسلم (2997)، احمد (10216)۔","e":"یہ چوہیا یا چوہا بھی فویسق حد سے گزرنے والے جانوروں میں شامل ہے۔ اس میں یہ بھی دلالت ہے کہ رات سوتے وقت آگ جلتی ہوئی چھوڑ کر نہ سوئیں، اسے بجھا دیں کہ چوہیا کو شیطانی کا موقع مل جاتا ہے اور گھر جلا کر خاکستر کر دیتی ہے۔ اور اس سے اسے مارنے کا حکم بھی ثابت ہوتا ہے۔ (عون المعبود: ۴/۵۳۳) ۲۔ باقی چوہیا کے مسخ ہونے کی بابت یہ نبی صلی اللہ علیہ وسلم نے کہی تھی مگر بعد میں آپ کو بتا دیا گیا جیسا کہ بندروں اور خنزیروں کے متعلق بتا دیا گیا تھا کہ یہ تبدیل شدہ نہیں اسی طرح چوہیا بھی تبدیل شدہ مخلوق نہیں یہ ایک خاص مخلوق ہے۔ (فتح الباری: ۶/۳۵۳)"}],[3970,"سیدنا عبداللہ ابن عمر رضی اللہ عنہ کہتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم کتوں کو مارنے کا حکم دیا کرتے تھے اور ہمیں مدینہ منورہ کی اطراف و جوانب میں روانہ کیا جاتا تھا اور ہم جو کتا دیکھتے اس کو مار دیتے تھے۔ یہاں تک کہ اگر کوئی دیہاتی عورت گذرتی جس کے ساتھ کتا جا رہا ہوتا تو ہم اس کو بھی مار ڈالتے تھے۔‘‘ (مسلم)","",{"k":"مسلم (1570)، بخاری (3324)، ترمذی (1490)، نسائی (4279)، ابن ماجہ (3204)، احمد (6299)، مؤطا (18091)، دارمی (2007)۔"}],[3971,"ایک روایت میں ہے کہ آنحضرت صلی اللہ علیہ وسلم نے کتوں کو مارنے کا حکم دیا مگر وہ کتا جو شکار کے لیے ہو یا جو بکریوں کا کتا ہو۔ جو مویشیوں کا کتا ہو وہ نہ مارا جائے۔ سیدنا عبداللہ ابن عمر رضی اللہ عنہ کو کہا گیا کہ ابو ہریرہ رضی اللہ عنہ نے کھیتی کا کتا بھی مستثنیٰ ذکر کیا ہے۔ تو انہوں نے کہا: ابو ہریرہ رضی اللہ عنہ کی کھیتی تھی۔‘‘ (مسلم)","",{"k":"مسلم (1571)، بخاری (3324)، ترمذی (1490)، نسائی (4279)، ابن ماجہ (3204)، احمد (6299)، مؤطا (18091)، دارمی (2007)۔"}],[3972,"سیدنا عبداللہ بن مغفل رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اگر کتے اقوام میں سے ایک قوم نہ ہوتی تو میں سب ہی کو قتل کرنے کا حکم دیتا پس تم ہر کالے سیاہ کو قتل کر دو۔‘‘ (ترمذی)","",{"k":"ترمذی (1486)، صحیح، البانی: 1201، مسلم (1573)، نسائی (4280)، ابوداؤد (2845)، ابن ماجہ (3205)، احمد (20039)۔"}],[3973,"سیدہ میمونہ رضی اللہ عنہا سے مروی ہے کہ ان کے پاس ایک دن رسول اللہ صلی اللہ علیہ وسلم فجر کے وقت پراگندہ خاطر تھے۔ تو اس نے عرض کیا: آج شروع دن سے آپ صلی اللہ علیہ وسلم کی صورت متغیر ہے؟ فرمایا: جبرئیل علیہ السلام نے وعدہ کیا تھا کہ وہ رات کو آ کر ملاقات کریں گے اور نہیں آئے۔ اللہ کی قسم! اس نے خلاف وعدہ مجھ سے نہیں کیا۔ پس یہ دن آپ صلی اللہ علیہ وسلم اسی حالت میں رہے۔ پھر آپ صلی اللہ علیہ وسلم کے دل مبارک میں خیال پیدا ہوا کہ یہاں کتے کا بچہ بھی تھا۔ آپ صلی اللہ علیہ وسلم نے حکم دیا اور وہ نکال دیا گیا، پھر آپ صلی اللہ علیہ وسلم نے پانی لے کر اس جگہ پر چھڑک دیا۔ رات ہوئی تو جبرئیل علیہ السلام تشریف لائے۔ آنحضرت صلی اللہ علیہ وسلم نے فرمایا: تم نے کل رات ملاقات کا وعدہ کیا تھا۔ اس نے کہا: ہاں، لیکن ہم اس گھر میں داخل نہیں ہوتے جس میں کتا ہو یا تصویر ہو۔ پس اس دن آپ صلی اللہ علیہ وسلم نے کتے مارنے کا حکم دیا تھا اور چھوٹے باغ کے کتے مارے گئے اور بڑے باغ کے کتے رہنے دیئے۔‘‘ (مسلم)","",{"k":"مسلم (2105)، نسائی (4283)، ابوداؤد (4157)، احمد (26260)۔"}],[3974,"ایک روایت میں ہے۔ یہاں تک کہ چھوٹے کتے بھی مارنے کا حکم دیدیا۔‘‘ (النسائی)","",{"k":"نسائی (4276)، صحیح، البانی: 3987، مسلم (2105)، ابوداؤد (4157)، احمد (26260)۔","e":"ان احادیث کا مفاد یہی ہے کہ کالے نقطہ والا کتا اب بھی مارنے کا حکم ہے۔ پہلے آپ صلی اللہ علیہ وسلم نے کتوں کو قتل کرنے کا حکم دیا تھا، اس کے بعد منع کر دیا تھا۔ لیکن کاٹنے والا کتا جس کی عام عادت ہو کہ وہ کاٹتا رہتا ہوا سے اب بھی مارنا جائز ہے۔ شکار اور حفاظت اور زراعت کے لیے کتے رکھنا جائز ہیں، تاہم آئندہ بھی ضرورت کے تحت ان احادیث سے تاثر یہی ملتا ہے کہ کبھی ضرورت پڑ جائے تو کتوں کو مارا جا سکتا ہے۔ مگر یہ ایک امت ہے، اس کی نسل کشی کر دینا جائز نہیں۔ (عون المعبود: ۳/۶۷) یہ بھی ثابت ہوا جہاں کتا یا تصویر ہو وہاں فرشتہ نہیں آتا۔"}],[3975,"سیدنا عبداللہ ابن عباس رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے ان چار حیوانوں کو مارنے کی مخالفت فرمائی ہے۔ چیونٹی، شہد کی مکھی، ہُد ہُد اور لٹورا پرندہ۔‘‘ (ابوداؤد)","",{"e":"ایک حدیث میں مینڈک کو بھی قتل کرنے کی ممانعت آتی ہے۔ (مسند احمد) آہ! میں قربان جاؤں پیغمبر آخر زماں صلی اللہ علیہ وسلم پر جنہوں نے ایسی صحت مندانہ اور حکیمانہ باتوں سے آگاہ کیا۔ چیونٹی کو نہ مارنے پر یہ حدیث بھی دلالت کرتی ہے کہ ایک نبی ایک درخت کے نیچے اترے انہیں، چیونٹی نے کاٹ لیا، انہوں نے حکم دیا کہ چیونٹیوں کی وادی کو آگ میں بھسم کر دو۔ تو اللہ تعالیٰ نے حکم دیا ایک چیونٹی جس نے کاٹا تھا، اس کو مارنا تھا، سب کو کیوں مارا۔ (بخاری: ۳۳۱۹) کتاب بدء الخلق، باب اذا وقع الذباب الخ. اس حدیث سے ثابت ہوا مذکورہ چیزوں کو مارنا اور انہیں کھانا بھی حرام ہے۔ ہد ہد اور ممولہ پرندے تو حلال ہیں مگر انہیں مارنے کی ممانعت ہے۔ (تفہیم الاسلام: ۲/۷۲۵)"}],[3976,"سیدنا سمرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ہر لڑکا عقیقہ کے لیے گروی ہوتا ہے اور اس کی طرف سے ساتویں دن ذبح کیا جاتا ہے، اس سے خون لگایا جاتا ہے۔‘‘ ابو قتادہ رضی اللہ عنہ نے اس کی تفسیر میں کہا ہے عقیقہ ذبح کر کے اس سے ایک ٹکڑا اون کا لے کر اس کے سر کی رگوں کے سامنے پکڑا جائے اور بچے کی سر کی چوٹی پر رکھا یہاں تک کہ دھاگہ کی مثل اس کے اوپر خوں بہنے لگے اور پھر سر دھو کر مونڈ دیا جائے۔ ابوداؤد نے کہا: ابو قتادہ کی یہ تفسیر منسوخ ہے اور یہ وہم ہے۔‘‘","",{"k":"ابوداؤد (2837)، صحیح، البانی: 2462، دون قولہ یدمی والمحفوظ ویسمی، بخاری (5472)، ترمذی (1522)، نسائی (4220)، ابن ماجہ (3165)، احمد (19743)، دارمی (1969)۔"}],[3977,"سیدنا بریدہ رضی اللہ عنہ کہتے ہیں کہ عہد جاہلیت میں جب ہم میں سے کسی کے ہاں لڑکا پیدا ہوتا تو بکری ذبح کر کے اس کا خون بچے کے سر پر لیپ کر دیتے۔ جب اسلام آیا تو ہم ساتویں دن بکری ذبح کرتے، اس کا سر مونڈتے اور اس کے سر پر زعفران لگاتے ہیں۔‘‘ (ابوداؤد)","",{"k":"ابوداؤد (2843)، حسن صحیح، البانی: 2469۔","e":"ثابت ہوا یہ جاہلیت کا طریقہ تھا کہ پیدا ہونے والے بچے کو سر پر خون لگاتے تھے۔ اسلام نے اس سے روکا ہے اور بچے کو خون آلود کرنے کی بجائے زعفران کا رنگ لگانے کی اجازت دی ہے، اور ساتویں دن اس کا سر منڈوایا جائے اور اس کا نام رکھا جائے۔ یہ بھی ثابت ہوا زعفران پاک ہے اس میں نشہ نہیں اگر ہوتا تو اس کے استعمال کی اجازت نہ دی جاتی۔ (عون المعبود: ۳/۶۵)"}],[3978,"سیدہ ام کرز رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: لڑکے کی طرف سے دو بکریاں اور لڑکی کی طرف سے ایک بکری ہے۔ تمہیں کوئی ضرور نہیں ہے کہ عقیقے کے حیوان مذکر ہوں یا وہ مونث ہوں۔‘‘ (نسائی)","",{"k":"نسائی (4218)، صحیح، البانی: 3934، ترمذی (1516)، ابوداؤد (2836)، ابن ماجہ (3162)، دارمی (1966)۔"}],[3979,"سیدنا عبداللہ ابن عباس رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے حسن رضی اللہ عنہ اور حسین رضی اللہ عنہ کی طرف سے ایک ایک مینڈھا عقیقہ کیا۔ (ابوداؤد)","",{"k":"ابوداؤد (2841)، صحیح، البانی: 2466، لكن في رواية النسائي كبشين كبشين وهو الاصح: 4219۔"}],[3980,"’’اور نسائی کی روایت ہے کہ دو دو مینڈھے عقیقہ کیے۔‘‘ (نسائی)","",{"k":"نسائی (4219)، صحيح، البانی: 3935۔","e":"عقیقہ ساتویں دن ہے، لیکن ایک حدیث سے ثابت ہوتا ہے اگر مجبوراً نہ ہو سکے تو پھر زندگی میں کسی وقت بھی کیا جا سکتا ہے۔ (بیہقی) ساتویں دن نام رکھیں تو بہتر ہے، اگرچہ جس دن بچہ پیدا ہو اس دن نام رکھنا بھی جائز ہے، اور بال ساتویں دن ہی منڈوائے جائیں۔ یہ بھی ثابت ہوا لڑکے کے عقیقہ میں دو بکرے اور لڑکی کے عقیقہ میں ایک بکرا ہے۔ لڑکے کے عقیقہ میں ایک بکرے کا جو آیا ہے، ایک تو صحیح ترین بات یہی ہے کہ دو بکروں کا ذکر ہے، دوسری بات یہ ہے اگر بالفرض ایک بھی ثابت ہے تو یہ تنگی کی حالت میں ہوگا وگرنہ لڑکے کے عقیقہ کے دو جانور ہی ہیں۔ عقیقہ کے بارے میں اختلاف ہے واجب ہے یا نہیں۔ جو اس کے واجب نہ ہونے کے قائل ہیں ان کی دلیل یہ ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: جو عقیقہ کرنا چاہے وہ لڑکے سے دو بکریاں اور لڑکی سے ایک بکری کے ساتھ عقیقہ کرے۔ (موطا: ۱۷، احمد: ۳۸۱/۶) اس میں چونکہ مرضی پر عقیقہ منحصر کیا گیا ہے، یہ کہتے ہیں واجب نہیں۔ راجح بات یہی ہے اگر مجبوری نہیں گنجائش ہے تو یہ قربانی کی مانند واجب ہے کیونکہ نبی صلی اللہ علیہ وسلم نے عقیقے کا حکم دیا ہے۔ اولاد ایک نعمت ہے اور نعمت کا شکریہ ادا کرنا ایک عبادت کا درجہ رکھتا ہے۔ اس لیے اس نعمت کے شکرانے کا طریقہ عقیقہ کی صورت میں بتایا گیا ہے۔ تاکہ دوست احباب غرباء، فقراء بھی اس خوشی میں شریک ہوں اور منعم حقیقی کا شکریہ بھی ادا ہو جائے۔ فطرتاً لڑکے کی ولادت پر انسان زیادہ خوش ہوتا ہے اس کے عقیقہ کے دو بکرے رکھ دیئے اور لڑکی کے عقیقہ پر ایک بکرا رکھا گیا ہے۔ (تفہیم الاسلام: ۲/۷۵۷)\nانتباہ: عقیقہ میں قربانی والے جانور کی قید نہیں یعنی دوندا وغیرہ ہونا تاہم جانور اچھے ہوں تو بہتر ہے۔\nیہودی لڑکے کا ایک بکرا ذبح کر کے عقیقہ کیا کرتے تھے۔ اور لڑکی کا عقیقہ نہ کرتے تھے۔ نبی اکرم صلی اللہ علیہ وسلم نے ان کی مخالفت کا حکم دیا۔ (ابوداؤد: ۲۸۴۲) اس سے ثابت ہوا یہودی عورت دشمن تھے، اسلام نے عورتوں کو اعلیٰ مقام دلایا اور انہیں نعمت الٰہی قرار دے کر ان کا عقیقہ کرنے کا حکم دیا۔ (حوالہ مذکورہ) ۲۔ عقیقہ کے ساتھ بچہ گروی ہے، اس کا مطلب یہ ہے کہ جس طرح گروی دینا لازمی ہے اسی طرح اگر والدین بچے کا عقیقہ نہیں کرتے تو بچہ زندگی بھر میں اسے ادا کرے وہ اس کا پابند ہے، جب بھی کرے گا وہ عقیقہ ہی ہوگا۔ (حوالہ مذکور)"}],[3981,"’’البزار اور الموصلی نے مزید عائشہ رضی اللہ عنہا سے مرفوع روایت کیا ہے کہ نومولود کا نام رکھنے پر یہ کہہ کر ذبح کرو، اللہ کے نام سے اللہ سب سے بڑا ہے، اے اللہ! تیری طرف سے اور تیرے لیے یہ فلاں کا عقیقہ ہے۔‘‘","",{"k":"بزار، موصلی: 4521، باختصار، ورجاله رجال الصحيح خلا شيخ ابي يعلى: اسحاق فانى لم اعرفه، هيثمي: 3985۔"}],[3982,"’’الصغیر میں جابر رضی اللہ عنہ کی روایت میں مزید یہ بیان ہے کہ آنحضرت صلی اللہ علیہ وسلم نے ان دونوں کا ساتویں دن ختنہ کرایا۔‘‘","",{"k":"طبرانی صغير: 891، وكبير وفيه، محمد بن ابى السرى وثقه ابن حبان وغيره وفيه لين، هيثمي: 6200۔","e":"انتباہ: ......ساتویں دن ہی ختنہ کرنا صحیح حدیث سے ثابت نہیں یہ حالات اور بچے کی صحت کے مطابق ہے۔ کیونکہ ختنہ کے لیے صحابہ کرام رضی اللہ عنہم سے مختلف عمر میں بچوں کے ختنے کرنے کا ذکر آتا ہے۔ بہر صورت ختنہ ایک فطرتی عمل ہے، نبی صلی اللہ علیہ وسلم نے اس کا حکم دیا ہے، بلکہ یہودیوں اور مسلمانوں میں امتیازی علامت ہے، اس کے لیے دن مقرر نہیں، یہ مفہوم آپ تحفۃ المولود ص ۱۵۹ پر ملاحظہ فرما سکتے ہیں۔"}],[3983,"’’الکبیر میں ابورافع رضی اللہ عنہ کی روایت میں ہے کہ ان دونوں کے کانوں میں رسول اللہ صلی اللہ علیہ وسلم نے وقت ولادت اذان بھی کہی ہے۔‘‘","",{"k":"طبرانی كبير: 962، ابوداؤد، خلا الاذان في اذن الحسين والامر به، وفيه حماد بن شعيب وهو ضعيف جداً، هيثمي: 6207۔"}],[3984,"’’اور رزین کی روایت میں ہے کہ حسن رضی اللہ عنہ کے کان میں آپ صلی اللہ علیہ وسلم نے سورت اخلاص بھی تلاوت کی ہے اور کھجور کی گھٹی دی ہے۔‘‘ (رزین)","",{"k":"رزین۔","e":"تحفۃ المولود کے محقق نے تو اسے ضعیف کہا ہے، مگر دیگر محدثین نے کم از کم اسے حسن درجہ کی قرار دیا ہے۔ اس لیے بچے کے کان میں اذان دینا مسنون عمل ہے۔ اس کی حکمت یہ ہے کہ سب سے پہلے بچے کے کان رب کبریاء کی عظمت سے ہی آشنا ہوں، اور سب سے پہلے اسلام کی گواہی ان میں داخل ہو اور اس سے پہلے کہ شیطان اپنا اثر جمائے اسے فطرت کی دعوت سے روشناس کرا دیا جاتا ہے۔ (صفحہ ۳۲ تحفہ) گٹھی کی بات تو درست ہے، سورۃ اخلاص کا ثبوت درست نہیں۔"}]])